describe('selectGalleryImages — single vs multi image (mirrors productListCardMapper.test.ts)', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...ON_SALE, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when every group has only 1 image', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        { viewType: 'swatch', images: [{ link: 'b.jpg' }] },
      ],
    };
    expect(selectGalleryImages(product)).toBeUndefined();
  });

  test('picks the image group with the most images', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        {
          viewType: 'large',
          images: [
            { link: 'b1.jpg', alt: 'front' },
            { link: 'b2.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(product)).toEqual([
      { src: 'b1.jpg', alt: 'front' },
      { src: 'b2.jpg', alt: 'back' },
    ]);
  });

  test('a multi-image product renders images in the mapper output too', () => {
    const product: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [
        ...(ON_SALE.imageGroups ?? []),
        {
          viewType: 'large',
          images: [
            { link: 'front.jpg', alt: 'front' },
            { link: 'back.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectRecentlyViewedFullHistoryCard(product, formatPrice)?.images).toEqual([
      { src: 'front.jpg', alt: 'front' },
      { src: 'back.jpg', alt: 'back' },
    ]);
  });
});

