import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto(
  'http://localhost:6006/iframe.html?id=commerce-zimmrecentlyviewedgrid--default&viewMode=story',
);
await page.waitForTimeout(800);

const cards = page.locator('[data-testid="product-card"]');
const count = await cards.count();
console.log('card count:', count);

const firstCard = cards.first();

const before = await firstCard.boundingBox();
console.log('BEFORE hover, first card rect:', JSON.stringify(before));

await firstCard.hover();
await page.waitForTimeout(400); // let any transition/reflow settle

const after = await firstCard.boundingBox();
console.log('AFTER hover, first card rect:', JSON.stringify(after));

// Check second card's position too — if the FIRST card grew taller/wider and pushed later grid
// items, the second card's top-left position would shift even though nothing was hovered on it.
const secondCard = cards.nth(1);
const secondBefore = await secondCard.boundingBox();
console.log('second card rect (after first card hover):', JSON.stringify(secondBefore));

await page.screenshot({ path: '.tmp-grid-hover.png', fullPage: true });

// Now check size chip clickability on the hovered (first) card.
const chip = firstCard.locator('[role="radio"], button, [data-testid*="size-chip"]').first();
const chipCount = await firstCard
  .locator('[role="radio"], [data-testid*="size-chip"]')
  .count();
console.log('size chip elements found on first card:', chipCount);

if (chipCount > 0) {
  const chipBox = await firstCard.locator('[role="radio"], [data-testid*="size-chip"]').first().boundingBox();
  console.log('first chip rect:', JSON.stringify(chipBox));
  if (chipBox) {
    const elementAtPoint = await page.evaluate(
      ({ x, y }) => {
        const el = document.elementFromPoint(x, y);
        return el
          ? { tag: el.tagName, role: el.getAttribute('role'), testid: el.getAttribute('data-testid'), text: el.textContent?.slice(0, 30) }
          : null;
      },
      { x: chipBox.x + chipBox.width / 2, y: chipBox.y + chipBox.height / 2 },
    );
    console.log('element actually at chip center point:', JSON.stringify(elementAtPoint));
  }

  const ariaCheckedBefore = await firstCard.locator('[role="radio"]').first().getAttribute('aria-checked').catch(() => 'n/a');
  console.log('aria-checked BEFORE click:', ariaCheckedBefore);
  await firstCard.locator('[role="radio"], [data-testid*="size-chip"]').first().click({ force: false }).catch((e) => console.log('CLICK ERROR:', e.message));
  await page.waitForTimeout(200);
  const ariaCheckedAfter = await firstCard.locator('[role="radio"]').first().getAttribute('aria-checked').catch(() => 'n/a');
  console.log('aria-checked AFTER click:', ariaCheckedAfter);
}

await browser.close();

