/**
 * Builds `count` distinct `plp`-shaped cards — this grid's own confirmed variation (see
 * index.tsx's own `cards` JSDoc) — with a real price and, on every third card, a badge, so this
 * story reads as a realistic Full History grid rather than a wall of bare placeholders.
 * `hoverImage`/`sizeChipValues` are real (not omitted) precisely so the `plp` variation's hover
 * behaviour — swap to a model photo, reveal a size-chip picker, hide the price — has something to
 * actually show when exercised; see the fixtures' own comment above for why omitting them was the
 * bug. `onSizeChipSelect` here is a placeholder only — every story below renders through
 * `LiveSizeSelectionGrid`, which replaces it with a real, stateful handler per card (see that
 * component's own docblock for why: Marcel found, live, 2026-09-08, that a no-op read as "size
 * chips aren't selectable" even though the click was reaching the real element correctly). Kept
 * present (not omitted) only because the `plp` member of `ZimmProductCardProps` requires it.
 * `onAddToBag` is genuinely omitted — not part of what this organism needs to demonstrate.
 */
const buildCards = (count: number): ZimmProductCardProps[] =>
  Array.from({ length: count }, (_, index) => {
    const id = `prod-${index + 1}`;
    return {
      id,
      variation: 'plp',
      name: `Natura Dress ${index + 1}`,
      headingLevel: 'h3',
      href: `/product/${id}`,
      primaryImage: PRIMARY_IMAGE,
      hoverImage: HOVER_IMAGE,
      currentPrice: '$595.00',
      badge: index % 3 === 0 ? 'Runway' : undefined,
      sizeChipValues: SIZE_CHIP_VALUES,
      onSizeChipSelect: () => {},
    };
  });

/**
 * Wraps `ZimmRecentlyViewedGrid` so each card's size-chip selection is genuinely live rather than
 * inert — same underlying need `zimmProductCard/index.stories.tsx`'s own `LiveSizeSelectionCard`
 * documents (`ZimmSizeChipGroup` is a correctly-controlled component; nothing selects itself), now
 * extended to a whole *grid* of independently-selectable cards rather than one. State is a single
 * `Record<cardId, selectedValue>` map — one entry per card — so selecting a size on one card can
 * never affect another's.
 *
 * `args.cards` stays exactly what the story declared (every `play` function below reads
 * `args.cards`/`args` directly, matching `zimmRecentlyViewedRail`/`zimmProductCard`'s own stories'
 * convention of asserting against the declared args, not a derived render tree) — only the JSX
 * actually mounted gets the live-selection override, via a locally-built array passed to the real
 * `ZimmRecentlyViewedGrid`.
 */
const LiveSizeSelectionGrid = (args: ZimmRecentlyViewedGridProps) => {
  const [selectedByCardId, setSelectedByCardId] = useState<Record<string, string | undefined>>({});
  const liveCards = args.cards.map((card) =>
    card.variation === 'plp' || card.variation === 'wishlist'
      ? {
          ...card,
          selectedSizeChipValue: selectedByCardId[card.id],
          onSizeChipSelect: (value: string) => setSelectedByCardId((prev) => ({ ...prev, [card.id]: value })),
        }
      : card,
  );
  return <ZimmRecentlyViewedGrid {...args} cards={liveCards} />;
};

