import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmrecentlyviewedgrid--default&viewMode=story');
await page.waitForTimeout(800);

const firstCard = page.locator('[data-testid="product-card"]').first();
await firstCard.hover();
await page.waitForTimeout(300);

const chips = firstCard.locator('[role="radio"]');
const before = await chips.nth(1).getAttribute('aria-checked'); // pick "S", not "XS", to avoid any default-selection ambiguity
console.log('chip[1] aria-checked BEFORE click:', before);
await chips.nth(1).click();
await page.waitForTimeout(200);
const after = await chips.nth(1).getAttribute('aria-checked');
console.log('chip[1] aria-checked AFTER click:', after);

// Confirm the OTHER card's own chips are unaffected (independent per-card state).
const secondCard = page.locator('[data-testid="product-card"]').nth(1);
await secondCard.hover();
await page.waitForTimeout(300);
const secondCardChip = secondCard.locator('[role="radio"]').nth(1);
const secondCardState = await secondCardChip.getAttribute('aria-checked');
console.log('second card chip[1] aria-checked (should still be false):', secondCardState);

await browser.close();

