import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({
  viewport: { width: 402, height: 1221 },
  hasTouch: true,
  isMobile: true,
});

// Confirm the media query genuinely does NOT match in this context, before checking anything else.
await page.goto('data:text/html,<html><body></body></html>');
const mediaCheck = await page.evaluate(() => ({
  hoverHover: window.matchMedia('(hover: hover)').matches,
  pointerFine: window.matchMedia('(pointer: fine)').matches,
}));
console.log('media query check (should both be false):', JSON.stringify(mediaCheck));

await page.goto(
  'http://localhost:6006/iframe.html?id=commerce-zimmrecentlyviewedgrid--default&viewMode=story',
);
await page.waitForTimeout(800);

const result = await page.evaluate(() => {
  const cards = Array.from(document.querySelectorAll('[data-testid="product-card"]'));
  return cards.map((card, i) => {
    const nameEl = card.querySelector('h3, [class*="name"]');
    const priceVisible = !!Array.from(card.querySelectorAll('*')).find(
      (el) => el.textContent?.trim() === '$595.00' && getComputedStyle(el).clipPath === 'none',
    );
    const chipsVisible = !!Array.from(card.querySelectorAll('[role="radio"]')).find(
      (el) => getComputedStyle(el.closest('[data-card-slot]') || el).clipPath === 'none',
    );
    return {
      index: i,
      text: card.textContent?.slice(0, 60),
      priceVisible,
      chipsVisible,
    };
  });
});
console.log(JSON.stringify(result, null, 2));

await page.screenshot({ path: '.tmp-mobile-hover-check.png', fullPage: true });

await browser.close();

