import { chromium } from 'playwright';

const PRODUCT_ID = '4673TS251';
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
const page = await context.newPage();

let productPayload = null;
page.on('response', async (response) => {
  const url = response.url();
  if (url.includes(PRODUCT_ID) && url.includes('products')) {
    try {
      const body = await response.json();
      if (body?.id === PRODUCT_ID || body?.data?.some?.((p) => p.id === PRODUCT_ID)) {
        productPayload = body;
        console.log('CAPTURED product payload from:', url);
      }
    } catch {
      // not JSON or not relevant
    }
  }
});

await page.goto(`http://localhost:3000/product/${PRODUCT_ID}`, { waitUntil: 'networkidle', timeout: 30000 });
await page.waitForTimeout(1500);

if (productPayload) {
  const product = productPayload.id ? productPayload : productPayload.data.find((p) => p.id === PRODUCT_ID);
  console.log('imageGroups viewTypes:', JSON.stringify((product.imageGroups ?? []).map((g) => ({
    viewType: g.viewType,
    variationValues: g.variationValues,
    imageCount: g.images?.length ?? 0,
    firstImageSrc: g.images?.[0]?.disBaseLink || g.images?.[0]?.link,
  })), null, 2));
} else {
  console.log('No product payload captured for', PRODUCT_ID, '-- checking window.__PRELOADED_STATE__ or SSR markup instead');
  const ssrData = await page.evaluate((pid) => {
    const scripts = Array.from(document.querySelectorAll('script'));
    for (const s of scripts) {
      if (s.textContent?.includes(pid) && s.textContent.includes('imageGroups')) {
        return s.textContent.slice(0, 200) + '...(found imageGroups+id in inline script)';
      }
    }
    return 'not found in inline scripts either';
  }, PRODUCT_ID);
  console.log(ssrData);
}

await page.screenshot({ path: '.tmp-pdp-screenshot.png' });

await browser.close();

