if (productPayload) {
  const product = productPayload.id ? productPayload : productPayload.data.find((p) => p.id === PRODUCT_ID);
  console.log('imageGroups viewTypes:', JSON.stringify((product.imageGroups ?? []).map((g) => ({
    viewType: g.viewType,
    variationValues: g.variationValues,
    imageCount: g.images?.length ?? 0,
    firstImageSrc: g.images?.[0]?.disBaseLink || g.images?.[0]?.link,
  })), null, 2));
} else {
  console.log('No direct product network response captured -- extracting from SSR-embedded state instead');
  const imageGroups = await page.evaluate((pid) => {
    const scripts = Array.from(document.querySelectorAll('script'));
    for (const s of scripts) {
      const text = s.textContent ?? '';
      if (text.includes(pid) && text.includes('imageGroups')) {
        // Find the product object containing this id, then pull its imageGroups array out via a
        // bracket-matching scan (the SSR blob isn't isolated JSON on its own, can't JSON.parse the
        // whole script tag directly).
        const idIndex = text.indexOf(`"id":"${pid}"`);
        if (idIndex === -1) continue;
        const searchWindow = text.slice(Math.max(0, idIndex - 200), idIndex + 8000);
        const igIndex = searchWindow.indexOf('"imageGroups"');
        if (igIndex === -1) continue;
        const arrStart = searchWindow.indexOf('[', igIndex);
        let depth = 0;
        let end = arrStart;
        for (let i = arrStart; i < searchWindow.length; i++) {
          if (searchWindow[i] === '[') depth++;
          if (searchWindow[i] === ']') depth--;
          if (depth === 0) {
            end = i + 1;
            break;
          }
        }
        try {
          return JSON.parse(searchWindow.slice(arrStart, end));
        } catch (e) {
          return { parseError: String(e), raw: searchWindow.slice(arrStart, arrStart + 500) };
        }
      }
    }
    return null;
  }, PRODUCT_ID);

  if (imageGroups) {
    console.log(
      'imageGroups viewTypes:',
      JSON.stringify(
        (Array.isArray(imageGroups) ? imageGroups : [imageGroups]).map((g) => ({
          viewType: g.viewType,
          variationValues: g.variationValues,
          imageCount: g.images?.length ?? 0,
          firstImageSrc: g.images?.[0]?.disBaseLink || g.images?.[0]?.link,
        })),
        null,
        2,
      ),
    );
  } else {
    console.log('Could not locate imageGroups for', PRODUCT_ID, 'in SSR state either.');
  }
}

