  test('every other image in the selected medium group becomes a fallback candidate, in order, excluding the primary', () => {
    const multiImageMedium: RecentlyViewedFullHistoryProduct = {
      ...ON_SALE,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            { disBaseLink: 'https://cdn.example.test/medium/0-primary.jpg', alt: 'Primary' },
            { disBaseLink: 'https://cdn.example.test/medium/1-fallback.jpg', alt: 'First fallback' },
          ],
        },
      ],
    };
    const card = selectRecentlyViewedFullHistoryCard(multiImageMedium, formatPrice);
    expect(card?.primaryImage).toEqual({ src: 'https://cdn.example.test/medium/0-primary.jpg', alt: 'Primary' });
    expect(card?.primaryImageFallbacks).toEqual([
      { src: 'https://cdn.example.test/medium/1-fallback.jpg', alt: 'First fallback' },
    ]);
  });

  test('a single-image medium group yields an empty fallback list, not undefined', () => {
    const card = selectRecentlyViewedFullHistoryCard(ON_SALE, formatPrice);
    expect(card?.primaryImageFallbacks).toEqual([]);
  });
});

