describe('selectRecentlyViewedCard — primaryImageFallbacks (2026-09-08, live defect: a broken image can sit ahead of working ones in the same group)', () => {
  test('every other image in the selected medium group becomes a fallback candidate, in order, excluding the primary', () => {
    const multiImageMedium: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            { disBaseLink: 'https://cdn.example.test/medium/0-primary.jpg', alt: 'Primary' },
            { disBaseLink: 'https://cdn.example.test/medium/1-fallback.jpg', alt: 'First fallback' },
            { disBaseLink: 'https://cdn.example.test/medium/2-fallback.jpg', alt: 'Second fallback' },
          ],
        },
      ],
    };
    const card = selectRecentlyViewedCard(multiImageMedium, formatPrice);
    expect(card?.primaryImage).toEqual({ src: 'https://cdn.example.test/medium/0-primary.jpg', alt: 'Primary' });
    expect(card?.primaryImageFallbacks).toEqual([
      { src: 'https://cdn.example.test/medium/1-fallback.jpg', alt: 'First fallback' },
      { src: 'https://cdn.example.test/medium/2-fallback.jpg', alt: 'Second fallback' },
    ]);
  });

  test('a fallback candidate with no usable src (no disBaseLink, no link) is dropped rather than passed through broken', () => {
    const oneUnusableFallback: RecentlyViewedProduct = {
      ...FULL,
      imageGroups: [
        {
          viewType: 'medium',
          images: [
            { disBaseLink: 'https://cdn.example.test/medium/0-primary.jpg', alt: 'Primary' },
            { alt: 'No src at all' },
            { disBaseLink: 'https://cdn.example.test/medium/2-fallback.jpg', alt: 'Second fallback' },
          ],
        },
      ],
    };
    const card = selectRecentlyViewedCard(oneUnusableFallback, formatPrice);
    expect(card?.primaryImageFallbacks).toEqual([
      { src: 'https://cdn.example.test/medium/2-fallback.jpg', alt: 'Second fallback' },
    ]);
  });

  test('a single-image medium group yields an empty fallback list, not undefined', () => {
    const card = selectRecentlyViewedCard(FULL, formatPrice);
    expect(card?.primaryImageFallbacks).toEqual([]);
  });
});

