import { chromium } from 'playwright';

const PRODUCT_ID = '4673TS251';
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
const page = await context.newPage();

// Step 1: visit the PDP for real, so markProductViewed writes it into this context's own
// localStorage exactly the way a real shopper's browser would.
await page.goto(`http://localhost:3000/product/${PRODUCT_ID}`, { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(2000);

const storedIds = await page.evaluate(() => {
  // Find whatever localStorage key this hook uses without assuming the exact name.
  const keys = Object.keys(localStorage).filter((k) => /recently.?viewed/i.test(k));
  return keys.map((k) => ({ key: k, value: localStorage.getItem(k) }));
});
console.log('localStorage recently-viewed keys after visiting PDP:', JSON.stringify(storedIds));

// Step 2: navigate to Cart, where the rail is wired in, same browser context (same localStorage).
await page.goto('http://localhost:3000/cart', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(2500);

const cardCheck = await page.evaluate((pid) => {
  const cards = Array.from(document.querySelectorAll('[data-testid="product-card"]'));
  const match = cards.find((c) => c.getAttribute('data-product-id') === pid);
  if (!match) return { found: false, totalCards: cards.length };
  const img = match.querySelector('img');
  return {
    found: true,
    totalCards: cards.length,
    imgSrc: img?.getAttribute('src'),
    imgNaturalWidth: img instanceof HTMLImageElement ? img.naturalWidth : null,
  };
}, PRODUCT_ID);
console.log('Rail card check on /cart:', JSON.stringify(cardCheck, null, 2));

if (cardCheck.found && cardCheck.imgSrc) {
  const imgResponse = await page.request.get(cardCheck.imgSrc).catch((e) => ({ status: () => `ERROR: ${e.message}` }));
  console.log('Actual HTTP status of the rendered <img> src:', imgResponse.status());
}

await page.screenshot({ path: '.tmp-cart-rail-screenshot.png', fullPage: false });

await browser.close();

