  hasRailTestId: !!document.querySelector('[data-testid="recently-viewed-rail"]'),
  hasRailGroupTestId: !!document.querySelector('[data-testid="recently-viewed-rail-group"]'),
}));
console.log('page diagnostic on /cart:', JSON.stringify(pageDiagnostic, null, 2));

const cardCheck = await page.evaluate((pid) => {
  const cards = Array.from(document.querySelectorAll('[data-testid="product-card"]'));
  const match = cards.find((c) => c.getAttribute('data-product-id') === pid);
  if (!match) return { found: false, totalCards: cards.length };
  const img = match.querySelector('img');
  return {
    found: true,
    totalCards: cards.length,
    imgSrc: img?.getAttribute('src'),
    imgNaturalWidth: img instanceof HTMLImageElement ? img.naturalWidth : null,
  };
}, PRODUCT_ID);
console.log('Rail card check on /cart:', JSON.stringify(cardCheck, null, 2));

if (cardCheck.found && cardCheck.imgSrc) {
  const imgResponse = await page.request.get(cardCheck.imgSrc).catch((e) => ({ status: () => `ERROR: ${e.message}` }));
  console.log('Actual HTTP status of the rendered <img> src:', imgResponse.status());
}

await page.screenshot({ path: '.tmp-cart-rail-screenshot.png', fullPage: false });

await browser.close();

