import { chromium } from 'playwright';

const PRODUCT_ID = '4673TS251';
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
const page = await context.newPage();

const consoleMessages = [];
page.on('console', (msg) => consoleMessages.push(`[${msg.type()}] ${msg.text()}`));
page.on('pageerror', (err) => consoleMessages.push(`[pageerror] ${err.message}`));

const requests = [];
page.on('request', (req) => {
  if (req.method() === 'POST' && /basket/i.test(req.url())) requests.push(req.url());
});

// Track a product, then go to the Full History page.
await page.goto(`http://localhost:3000/product/${PRODUCT_ID}`, { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(1500);
await page.goto('http://localhost:3000/recently-viewed', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(3000);

const before = await page.evaluate(() => {
  const chip = document.querySelector('[role="radio"]');
  const bagButton = Array.from(document.querySelectorAll('button')).find((b) =>
    /add to bag/i.test(b.textContent ?? ''),
  );
  return {
    chipFound: !!chip,
    chipAriaChecked: chip?.getAttribute('aria-checked'),
    bagButtonFound: !!bagButton,
    bagButtonDisabled: bagButton instanceof HTMLButtonElement ? bagButton.disabled : null,
  };
});
console.log('BEFORE click:', JSON.stringify(before, null, 2));

await page.click('[role="radio"]');
await page.waitForTimeout(500);

const afterChipClick = await page.evaluate(() => {
  const chip = document.querySelector('[role="radio"]');
  return { chipAriaChecked: chip?.getAttribute('aria-checked') };
});
console.log('AFTER chip click:', JSON.stringify(afterChipClick, null, 2));

const bagButtonHandle = await page.$('button:has-text("Add to Bag"), button:has-text("ADD TO BAG")');
if (bagButtonHandle) {
  await bagButtonHandle.click();
  await page.waitForTimeout(1000);
}

console.log('POST /basket requests observed:', JSON.stringify(requests));
console.log('console/page errors observed:', JSON.stringify(consoleMessages.slice(0, 20), null, 2));

await browser.close();

