import { chromium } from 'playwright';

async function diagnose(page, label) {
  console.log(`\n=== ${label} ===`);
  const result = await page.evaluate(() => {
    const chip = document.querySelector('[data-testid="size-chip"]');
    if (!chip) return { error: 'no size chip found' };

    const overlay = document.querySelector('a[href*="/product/"]');

    const describe = (el, name) => {
      if (!el) return { name, missing: true };
      const cs = getComputedStyle(el);
      return {
        name,
        tag: el.tagName,
        dataCardSlot: el.getAttribute('data-card-slot'),
        position: cs.position,
        zIndex: cs.zIndex,
        clipPath: cs.clipPath,
        transform: cs.transform,
        isolation: cs.isolation,
      };
    };

    // Walk up from the chip to the content root, describing every ancestor.
    const chain = [];
    let el = chip;
    let depth = 0;
    while (el && depth < 8) {
      chain.push(describe(el, `ancestor[${depth}]`));
      el = el.parentElement;
      depth++;
    }

    const elementAtChipCenter = (() => {
      const rect = chip.getBoundingClientRect();
      const atPoint = document.elementFromPoint(rect.x + rect.width / 2, rect.y + rect.height / 2);
      return atPoint
        ? { tag: atPoint.tagName, testid: atPoint.getAttribute('data-testid'), href: atPoint.getAttribute('href') }
        : null;
    })();

    return {
      chipChain: chain,
      overlay: describe(overlay, 'overlay-link'),
      elementAtChipCenter,
    };
  });
  console.log(JSON.stringify(result, null, 2));
}

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });

// Full History page
const page1 = await context.newPage();
await page1.goto('http://localhost:3000/product/4673TS251', { waitUntil: 'load', timeout: 30000 });
await page1.waitForTimeout(1500);
await page1.goto('http://localhost:3000/recently-viewed', { waitUntil: 'load', timeout: 30000 });
await page1.waitForTimeout(2500);
await page1.hover('[data-testid="product-card"]');
await page1.waitForTimeout(300);
await diagnose(page1, 'Full History page (/recently-viewed)');

// Real PLP page, for comparison
const page2 = await context.newPage();
await page2.goto('http://localhost:3000/category/womens-clothing', { waitUntil: 'load', timeout: 30000 }).catch(() => {});
await page2.waitForTimeout(2500);
const plpHasCard = await page2.evaluate(() => !!document.querySelector('[data-testid="product-card"]'));
console.log('\nPLP page loaded, has product-card:', plpHasCard, 'url:', page2.url());
if (plpHasCard) {
  await page2.hover('[data-testid="product-card"]');
  await page2.waitForTimeout(300);
  await diagnose(page2, 'Real PLP page');
}

await browser.close();

