import { getSlasToken } from './scripts/sfcc/_shared.mjs';

const siteId = process.env.COMMERCE_API_SITE_ID;
const { COMMERCE_API_SHORT_CODE, COMMERCE_API_ORGANIZATION_ID } = process.env;
const token = await getSlasToken(siteId);

const params = new URLSearchParams({
  siteId,
  q: '',
  limit: '25',
  perPricebook: 'true',
  allVariationProperties: 'true',
  allImages: 'true',
  expand: 'promotions,variations,prices,images,page_meta_tags,custom_properties',
});
const url = `https://${COMMERCE_API_SHORT_CODE}.api.commercecloud.salesforce.com/product/shopper-search/v1/organizations/${COMMERCE_API_ORGANIZATION_ID}/product-search?${params}`;

const response = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
console.log('HTTP', response.status);
const body = await response.json();
const hits = body.hits ?? [];
console.log('total hits:', body.total, '| returned:', hits.length);

const withTieredPrices = hits.find((h) => Array.isArray(h.tieredPrices) && h.tieredPrices.length > 1);
const withVariants = hits.find((h) => Array.isArray(h.variants) && h.variants.length > 0);

console.log('\n=== a hit with >1 tieredPrices entry (real was/now candidate) ===');
console.log(
  withTieredPrices
    ? JSON.stringify(
        { productId: withTieredPrices.productId, productName: withTieredPrices.productName, price: withTieredPrices.price, tieredPrices: withTieredPrices.tieredPrices },
        null,
        2,
      )
    : 'NONE FOUND in this page of results',
);

console.log('\n=== a hit with a populated variants array ===');
console.log(
  withVariants
    ? JSON.stringify(
        { productId: withVariants.productId, productName: withVariants.productName, representedProduct: withVariants.representedProduct, variants: withVariants.variants.slice(0, 3) },
        null,
        2,
      )
    : 'NONE FOUND in this page of results',
);

console.log('\n=== first hit raw keys (sanity check on shape) ===');
console.log(hits[0] ? Object.keys(hits[0]) : 'no hits');

