import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

let captured = null;
page.on('response', async (response) => {
  const url = response.url();
  if (/product-search/i.test(url) && response.request().method() === 'GET') {
    try {
      const body = await response.json();
      if (body?.hits) captured = { url, body };
    } catch {}
  }
});

await page.goto('http://localhost:3000/category/womens-clothing', { waitUntil: 'load', timeout: 30000 }).catch(() => {});
await page.waitForTimeout(4000);

if (!captured) {
  console.log('No product-search response captured. Trying a broader category path...');
  await page.goto('http://localhost:3000/category/womens', { waitUntil: 'load', timeout: 30000 }).catch(() => {});
  await page.waitForTimeout(4000);
}

if (captured) {
  console.log('Captured URL:', captured.url);
  const hits = captured.body.hits ?? [];
  console.log('total:', captured.body.total, 'returned:', hits.length);
