140	/**
141	 * Quick test integration only (SFCC-83/84) — swaps the base `ProductTile` for the shared
142	 * `ZimmProductCard` (`variation: 'plp'`) so it can be exercised against a real PLP grid. Not the
143	 * final PLP implementation: it still needs the "product card group" component this grid doesn't
144	 * have yet. Owns its own `selectedSizeChipValue` local state — same pattern
145	 * `organisms/zimmProductCard/index.stories.tsx`'s own `LiveSizeSelectionCard` already uses —
146	 * since the page renders many of these and this can't be a single page-level state variable.
147	 */
148	type ProductListCardProps = Extract<ZimmProductCardProps, { variation: 'plp' }>;
149	
150	const ProductListCard = (cardProps: ProductListCardProps) => {
151	  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(
152	    () => cardProps.selectedSizeChipValue,
153	  );
154	  const handleSizeChipSelect = (value: string) => {
155	    setSelectedSizeChipValue(value);
156	    cardProps.onSizeChipSelect?.(value);
157	  };
