 * since the page renders many of these and this can't be a single page-level state variable.
 *
 * **Also resolves the real orderable variant for Add to Bag (2026-09-08, Gap 3 fix).** This is
 * the one component that ever knows which size is currently selected — `handleAddToBag` below is
 * built in the parent's render loop, with no access to this component's own local state, so
 * variant resolution has to happen here, not there. `hit` and `onResolvedAddToBag` are this
 * component's own props (not part of `ZimmProductCardProps` at all — `ZimmProductCard` itself
 * still only ever receives a plain, no-argument `onAddToBag`, matching its existing, unchanged
 * contract for every variation).
 */
type ProductListCardProps = Extract<ZimmProductCardProps, { variation: 'plp' }> & {
  hit: ProductListSearchHit;
  onResolvedAddToBag: (productId: string, price: number | undefined) => void;
};

const ProductListCard = ({ hit, onResolvedAddToBag, ...cardProps }: ProductListCardProps) => {
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(
    () => cardProps.selectedSizeChipValue,
  );
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    cardProps.onSizeChipSelect?.(value);
  };
  const handleAddToBag = () => {
    // No selection -> today's existing default-variant behaviour, unchanged (build plan's own
    // "without size -> default size" expectation). A selection that somehow matches no real
    // variant falls back the same way, rather than blocking the add entirely on a data mismatch.
    const resolved = selectedSizeChipValue ? resolveOrderableVariant(hit, selectedSizeChipValue) : null;
    const orderableProductId = resolved?.productId ?? hit.representedProduct?.id ?? hit.productId;
    onResolvedAddToBag(orderableProductId, resolved?.price ?? hit.price);
  };

  return (
    <ZimmProductCard
      {...cardProps}
      selectedSizeChipValue={selectedSizeChipValue}
      onSizeChipSelect={handleSizeChipSelect}
      onAddToBag={handleAddToBag}
    />
  );
};

