import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });

await page.goto('http://localhost:3000/category/clothing', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(3000);

const cards = page.locator('[data-testid="product-card"]');
const count = await cards.count();
console.log('cards on page:', count);

// Survey every card for isUnavailable (disabled bag) and was/now pricing, without assuming which
// index has which state.
for (let i = 0; i < count; i++) {
  const card = cards.nth(i);
  await card.hover();
  await page.waitForTimeout(150);
  const bagButton = card.getByRole('button', { name: 'Add to bag' });
  const notifyButton = card.getByRole('button', { name: 'Notify me' });
  const isDisabled = (await bagButton.count()) > 0 ? await bagButton.isDisabled() : null;
  const hasNotify = (await notifyButton.count()) > 0;
  const priceTexts = await card.locator('*').evaluateAll((els) =>
    els
      .filter((el) => el.children.length === 0 && /\$/.test(el.textContent ?? ''))
      .map((el) => el.textContent),
  );
  console.log(`card[${i}]: bagDisabled=${isDisabled}, hasNotifyMe=${hasNotify}, prices=${JSON.stringify([...new Set(priceTexts)])}`);
}

await browser.close();

