const PRODUCT_ID = '4673TS251';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });

await page.goto('http://localhost:3000/category/clothing', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(3000);

const card = page.locator(`[data-testid="product-card"][data-product-id="${PRODUCT_ID}"]`);
const cardCount = await card.count();
console.log('card found on /category/clothing:', cardCount > 0);

if (cardCount === 0) {
  console.log('Not on this category page — checking womens-clothing search results some other way is needed.');
  await browser.close();
  process.exit(0);
}

await card.hover();
await page.waitForTimeout(300);

const chips = await card.locator('[data-testid="size-chip"]').evaluateAll((els) =>
  els.map((el) => ({
    value: el.getAttribute('data-size-value'),
    text: el.textContent,
    disabledAttr: el.hasAttribute('disabled'),
    ariaDisabled: el.getAttribute('aria-disabled'),
  })),
);
console.log('Rendered size chips for', PRODUCT_ID, ':', JSON.stringify(chips, null, 2));

// Find the raw SSR-embedded data for this exact size value's orderable flag, to see what the
// search hit itself actually carries (as opposed to the Product Detail endpoint checked earlier).
const rawSnippet = await page.evaluate((pid) => {
  const scripts = Array.from(document.querySelectorAll('script'));
  for (const s of scripts) {
    const text = s.textContent ?? '';
    const idIdx = text.indexOf(`"productId":"${pid}"`);
    if (idIdx === -1) continue;
    // Search forward from the product's own id for the "1 (US 6)" name string, within a
    // reasonable window (variationAttributes should be relatively close to productId).
    const window_ = text.slice(idIdx, idIdx + 6000);
    const nameIdx = window_.indexOf('1 (US 6)');
    if (nameIdx === -1) continue;
    return window_.slice(Math.max(0, nameIdx - 150), nameIdx + 150);
  }
  return null;
}, PRODUCT_ID);
console.log('\nRaw SSR snippet around "1 (US 6)":\n', rawSnippet);

await browser.close();

