import re, json
with open('$CLAUDE_JOB_DIR/tmp/plp_page.html') as f:
    text = f.read()
m = re.search(r'<script id=\"mobify-data\" type=\"application/json\">(.*?)</script>', text, re.S)
data = json.loads(m.group(1))

def find_hit(obj, target_id):
    if isinstance(obj, dict):
        if obj.get('productId') == target_id and 'imageGroups' in obj:
            return obj
        for v in obj.values():
            r = find_hit(v, target_id)
            if r is not None:
                return r
    elif isinstance(obj, list):
        for v in obj:
            r = find_hit(v, target_id)
            if r is not None:
                return r
    return None

for pid in ['4673TS251', 'ZWNEWPRD04']:
    hit = find_hit(data, pid)
    print(f'=== {pid} — hit.image ===')
    print(' ', (hit.get('image') or {}).get('disBaseLink'))
    print(f'=== {pid} — every viewType, first image only ===')
    for vt in ['hi-res', 'large', 'medium', 'small', 'swatch']:
        groups = [g for g in hit.get('imageGroups', []) if g.get('viewType') == vt]
        for i, g in enumerate(groups):
            colour_tag = None
            for a in g.get('variationAttributes', []):
                if a.get('id') == 'color':
                    colour_tag = [v.get('value') for v in a.get('values', [])]
            first_img = (g.get('images') or [{}])[0].get('disBaseLink')
            print(f'  {vt} (group {i}, colour={colour_tag}):', first_img)
    print()
"

