describe('resolveRepresentativeColour (2026-09-09 fix: colour-aware image resolution)', () => {
  test('resolves the real colour SFCC already picked, via representedProduct.id matched against variants', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'prod-1-BLK' },
      variants: [
        { productId: 'prod-1-BLK', variationValues: { color: 'BLK', size: '0' } },
        { productId: 'prod-1-TAN', variationValues: { color: 'TAN', size: '0' } },
      ],
    };
    expect(resolveRepresentativeColour(hit)).toBe('BLK');
  });

  test('returns undefined when there is no representedProduct at all', () => {
    expect(resolveRepresentativeColour(baseHit)).toBeUndefined();
  });

  test('returns undefined when representedProduct.id matches no real variant', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'does-not-exist' },
      variants: [{ productId: 'prod-1-BLK', variationValues: { color: 'BLK', size: '0' } }],
    };
    expect(resolveRepresentativeColour(hit)).toBeUndefined();
  });

  test('returns undefined for a genuinely single-colour product (variant has no colour value)', () => {
    const hit = {
      ...baseHit,
      representedProduct: { id: 'prod-1-0' },
      variants: [{ productId: 'prod-1-0', variationValues: { size: '0' } }],
    };
    expect(resolveRepresentativeColour(hit)).toBeUndefined();
  });
});

describe('selectGalleryImages (2026-09-09 fix: viewType + colour scoped, not "most images anywhere")', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...baseHit, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when the medium group has only 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [{ viewType: 'medium', images: [{ link: 'a.jpg' }] }],
    };
    expect(selectGalleryImages(hit)).toBeUndefined();
  });

  test('picks the medium-viewType group, never a large/small group with more images', () => {
    // Fail-first requirement: 'large' here has strictly MORE images than 'medium' -- a test that
    // only checked "some gallery renders" would pass under either the old ("most images anywhere")
    // or the new (viewType-scoped) implementation. This fixture only passes under the new one.
    const hit = {
      ...baseHit,
      imageGroups: [
        {
          viewType: 'large',
          images: [{ link: 'wrong-1.jpg' }, { link: 'wrong-2.jpg' }, { link: 'wrong-3.jpg' }],
        },
        {
          viewType: 'medium',
          images: [
            { link: 'b1.jpg', alt: 'front' },
            { link: 'b2.jpg', alt: 'back' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: 'b1.jpg', alt: 'front' },
      { src: 'b2.jpg', alt: 'back' },
    ]);
  });

  test('picks only the representative colour\'s medium images, not a different colour\'s (mirrors a real 2-colour product)', () => {
    // Fail-first requirement: BLK has FEWER images than TAN here -- a test where the right
    // colour happens to also have the most images wouldn't distinguish "picks by colour" from
    // "picks by most images" (the old, wrong behaviour). This fixture only passes when the
    // colour filter is genuinely applied, not just coincidentally correct.
    const hit = {
      ...baseHit,
      representedProduct: { id: 'prod-1-BLK' },
      variants: [
        { productId: 'prod-1-BLK', variationValues: { color: 'BLK', size: '0' } },
        { productId: 'prod-1-TAN', variationValues: { color: 'TAN', size: '0' } },
      ],
      imageGroups: [
        {
          viewType: 'medium',
          variationAttributes: [{ id: 'color', values: [{ value: 'TAN' }] }],
          images: [{ link: 'tan-1.jpg' }, { link: 'tan-2.jpg' }, { link: 'tan-3.jpg' }],
        },
        {
          viewType: 'medium',
          variationAttributes: [{ id: 'color', values: [{ value: 'BLK' }] }],
          images: [{ link: 'blk-1.jpg' }, { link: 'blk-2.jpg' }],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: 'blk-1.jpg', alt: '' },
      { src: 'blk-2.jpg', alt: '' },
    ]);
  });

  test('falls back to the medium group with no colour tag when the representative colour cannot be resolved', () => {
    const hit = {
      ...baseHit,
      // No representedProduct/variants at all -- resolveRepresentativeColour returns undefined,
      // so this must still degrade to a real, viewType-scoped (not fully unscoped) answer.
      imageGroups: [
        {
          viewType: 'medium',
          images: [{ link: 'c1.jpg' }, { link: 'c2.jpg' }],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: 'c1.jpg', alt: '' },
      { src: 'c2.jpg', alt: '' },
    ]);
  });
});

describe('selectProductListCard — hoverImage / primaryImageFallbacks (2026-09-09 fixes)', () => {
  const multiColourHit = {
    ...baseHit,
    representedProduct: { id: 'prod-1-BLK' },
    variants: [
      { productId: 'prod-1-BLK', variationValues: { color: 'BLK', size: '0' } },
      { productId: 'prod-1-TAN', variationValues: { color: 'TAN', size: '0' } },
    ],
    imageGroups: [
      {
        viewType: 'medium',
        variationAttributes: [{ id: 'color', values: [{ value: 'BLK' }] }],
        images: [
          { link: 'blk-1.jpg', alt: 'front' },
          { link: 'blk-2.jpg', alt: 'back' },
        ],
      },
      {
        viewType: 'medium',
        variationAttributes: [{ id: 'color', values: [{ value: 'TAN' }] }],
        images: [{ link: 'tan-1.jpg' }],
      },
    ],
  };

  test('hoverImage is the representative colour\'s second scoped image', () => {
    const card = selectProductListCard(multiColourHit, formatPrice);
    expect(card?.hoverImage).toEqual({ src: 'blk-2.jpg', alt: 'back' });
  });

  test('hoverImage is undefined when the scoped group has only 1 image', () => {
    const hit = { ...baseHit, imageGroups: [{ viewType: 'medium', images: [{ link: 'a.jpg' }] }] };
    expect(selectProductListCard(hit, formatPrice)?.hoverImage).toBeUndefined();
  });

  test('primaryImageFallbacks carries the full representative-colour scoped array, independent of primaryImage', () => {
    const card = selectProductListCard(multiColourHit, formatPrice);
    // primaryImage comes from the hit's own flat `image` field (baseHit's), an entirely separate
    // resolution from the scoped medium group -- confirmed live 2026-09-09 these are commonly
    // different images/viewTypes for the same real product, so there's no index to exclude here.
    expect(card?.primaryImage).toEqual({ src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' });
    expect(card?.primaryImageFallbacks).toEqual([
      { src: 'blk-1.jpg', alt: 'front' },
      { src: 'blk-2.jpg', alt: 'back' },
    ]);
  });

  test('primaryImageFallbacks is an empty array, not undefined, when there is nothing to fall back to', () => {
    expect(selectProductListCard(baseHit, formatPrice)?.primaryImageFallbacks).toEqual([]);
  });
});

