    expect(selectGalleryImages(hit)).toEqual([
      { src: 'c1.jpg', alt: '' },
      { src: 'c2.jpg', alt: '' },
    ]);
  });
});

describe('selectProductListCard — hoverImage / primaryImageFallbacks (2026-09-09 fixes)', () => {
  const multiColourHit = {
    ...baseHit,
    representedProduct: { id: 'prod-1-BLK' },
    variants: [
      { productId: 'prod-1-BLK', variationValues: { color: 'BLK', size: '0' } },
      { productId: 'prod-1-TAN', variationValues: { color: 'TAN', size: '0' } },
    ],
    imageGroups: [
      {
        viewType: 'medium',
        variationAttributes: [{ id: 'color', values: [{ value: 'BLK' }] }],
        images: [
          { link: 'blk-1.jpg', alt: 'front' },
          { link: 'blk-2.jpg', alt: 'back' },
        ],
      },
      {
        viewType: 'medium',
        variationAttributes: [{ id: 'color', values: [{ value: 'TAN' }] }],
        images: [{ link: 'tan-1.jpg' }],
      },
    ],
  };

  test('hoverImage is the representative colour\'s second scoped image', () => {
    const card = selectProductListCard(multiColourHit, formatPrice);
    expect(card?.hoverImage).toEqual({ src: 'blk-2.jpg', alt: 'back' });
  });

  test('hoverImage is undefined when the scoped group has only 1 image', () => {
    const hit = { ...baseHit, imageGroups: [{ viewType: 'medium', images: [{ link: 'a.jpg' }] }] };
    expect(selectProductListCard(hit, formatPrice)?.hoverImage).toBeUndefined();
  });

  test('primaryImageFallbacks carries the full representative-colour scoped array, independent of primaryImage', () => {
    const card = selectProductListCard(multiColourHit, formatPrice);
    // primaryImage comes from the hit's own flat `image` field (baseHit's), an entirely separate
    // resolution from the scoped medium group -- confirmed live 2026-09-09 these are commonly
    // different images/viewTypes for the same real product, so there's no index to exclude here.
    expect(card?.primaryImage).toEqual({ src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' });
    expect(card?.primaryImageFallbacks).toEqual([
      { src: 'blk-1.jpg', alt: 'front' },
      { src: 'blk-2.jpg', alt: 'back' },
    ]);
  });

  test('primaryImageFallbacks is an empty array, not undefined, when there is nothing to fall back to', () => {
    expect(selectProductListCard(baseHit, formatPrice)?.primaryImageFallbacks).toEqual([]);
  });
});

