1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmSlideIndicator } from '../zimmSlideIndicator';
5	import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
6	import { CARD_SLOT } from '../../zimmProductCardShared';
7	
8	/**
9	 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
10	 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
11	 * these descendants for hover-reveal styling without reaching into implementation details.
12	 * Do not rename these values without updating that recipe too:
13	 *   - "media"     — the outermost element (this component's root)
14	 *   - "badge"     — the merchandiser badge label, top-left of the image (present only when a
15	 *                   non-empty `badge` is supplied)
16	 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
17	 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
18	 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
19	 */
20	
21	const messages = defineMessages({
22	  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
23	  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
24	  /**
25	   * Accessible name for the always-available keyboard-operable scroll container (WCAG 2.1.1) —
26	   * distinct from the hover-capable-only `carousel` arrows and the touch-only
27	   * `indicatorWrapper`, this is the underlying paging affordance that exists regardless of
28	   * pointer capability. See `canNavigateByKeyboard` below.
29	   */
30	  galleryLabel: { id: 'product_card_media.gallery.label', defaultMessage: 'Product images' },
31	});
32	
33	const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';
34	
35	/** One image the card can show — always a real, non-empty product-photo description. */
36	export type ZimmProductCardMediaImage = {
37	  src: string;
38	  alt: string;
39	};
40	
41	export type ZimmProductCardMediaProps = {
42	  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
43	  primaryImage: ZimmProductCardMediaImage;
44	  /**
45	   * Ordered backup candidates tried, one at a time, only if `primaryImage` itself fails to load
46	   * (a real browser `onError` — the URL 404s or otherwise never resolves; a real, live case: a
47	   * catalog image group can have a broken image sitting ahead of working ones in the same
48	   * group). Not a gallery — no arrows, no slide indicator, no effect on `totalSlides` — this is
49	   * purely "if the primary image is dead, quietly try the next candidate instead of showing a
50	   * broken image," scoped to the primary slide only (`hoverImage` and `images` have no fallback
51	   * of their own; out of scope for the live bug this was added for). Omitted or empty behaves
52	   * exactly like before this prop existed: no fallback, a failed `primaryImage` just fails.
53	   */
54	  primaryImageFallbacks?: ZimmProductCardMediaImage[];
55	  /**
56	   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
57	   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
58	   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
59	   * a hover-swap of just the first two would be a second, inconsistent way to see the same
60	   * content. Has no effect unless `swapOnHover` is also true.
61	   */
62	  hoverImage?: ZimmProductCardMediaImage;
63	  /**
64	   * The full orderable gallery for this card. Only takes over from `primaryImage` when it has
65	   * more than one entry — 0 or 1 entries behaves exactly like an absent `images` (see
66	   * `hoverImage`'s note above for why the two features don't combine).
67	   */
68	  images?: ZimmProductCardMediaImage[];
69	  /** Enables the primary/hover crossfade described on `hoverImage`. Has no effect without it. */
70	  swapOnHover: boolean;
71	  /**
72	   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
73	   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
74	   * — it renders whenever there is more than one image to page through, regardless of this prop.
75	   */
76	  showControls: boolean;
77	  /**
78	   * Merchandiser-configured badge label (e.g. "Runway", "Exclusive") — SFCC-236's Figma "Tag"
79	   * overlay, top-left of the image. Renders only when non-empty; a blank/whitespace-only value
80	   * behaves identically to omitting the prop, same guard shape as `removeLabel` below. Which
81	   * variations actually show a badge (PLP/Wishlist yes, Home no) is the organism's job via its
82	   * `VARIATION_CONFIG` — this component only renders what it's given.
83	   */
84	  badge?: string;
85	  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
86	  onRemove?: () => void;
87	  /**
88	   * Accessible name for the remove button — required in practice whenever `onRemove` is passed
89	   * (typically the product name, e.g. "Remove {productName} from wishlist"). Modelled as two
90	   * independent optional props rather than a discriminated union because this is a simple
91	   * co-requirement, not a real variant split: if `onRemove` is supplied without a usable
92	   * (non-empty, non-whitespace) `removeLabel`, the remove button silently does not render at
93	   * all rather than shipping an unlabelled, inaccessible button — see the component body.
94	   */
95	  removeLabel?: string;
96	  /**
97	   * LCP escape hatch for the primary image slot. Defaults to lazy-loading — this component has
98	   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
99	   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
100	   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
101	   */
102	  priority?: boolean;
103	  /**
104	   * Optional click handler on this component's own root — forwarded as-is, with no navigation
105	   * logic of its own (Media stays navigation-agnostic; the composing organism decides what a
106	   * click means and which of Media's own buttons to exclude from it). Added for SFCC-236 Fix I —
107	   * see the composing `ZimmProductCard` organism's own docblock for the full narrative.
108	   */
109	  onClick?: React.MouseEventHandler<HTMLDivElement>;
110	};
111	
112	/**
113	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
114	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the wishlist-remove
115	 * overlay slot. Figma "Image Group" component set, node 40002742:46323.
116	 *
117	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
118	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
119	 * the slide indicator are mutually exclusive by pointer capability
120	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
121	 * exist in the DOM at all times, gated via CSS rather than a JS `window.matchMedia` check —
122	 * matching the "keep in DOM, hide via CSS" precedent `ZimmColourSwatchGroup` already uses for its
123	 * off-page swatches — so server and client render identically (no hydration mismatch) and
124	 * neither affordance depends on `matchMedia`, which jsdom (this component's own Vitest
125	 * environment) does not implement. The two affordances differ in *where* that CSS lives, though:
126	 * the indicator is fully gated by this recipe's own media query. The arrows are not — this
127	 * recipe only ever sets them to `display: none`; the actual reveal (`display: flex`, on
128	 * `&:hover`/`&:has(:focus-visible)`) lives in the composing `ZimmProductCard` organism's own recipe,
129	 * since the AC and Figma both specify arrows appear on an actual hover/focus interaction with the
130	 * whole card, not merely "device supports hover" — the same interaction-gated pattern already
131	 * used there for price/size-chips/notify-me. A story rendering this component standalone (see
132	 * this file's own `index.stories.tsx`) therefore never shows the arrows, by design.
133	 *
134	 * A third, always-available operability layer sits underneath both visual affordances: the
135	 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
136	 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
137	 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
138	 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
139	 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
140	 */
141	export const ZimmProductCardMedia = ({
142	  primaryImage,
143	  primaryImageFallbacks,
144	  hoverImage,
145	  images,
146	  swapOnHover,
147	  showControls,
148	  badge,
149	  onRemove,
150	  removeLabel,
151	  priority,
152	  onClick,
153	}: ZimmProductCardMediaProps) => {
154	  const intl = useIntl();
155	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
156	
157	  // Cascading primary-image fallback — see that prop's own JSDoc. `primaryCandidateIndex` names
158	  // a position in `primaryCandidates`, not a src directly, so a re-render after `images`/
159	  // `primaryImage` itself changes (e.g. a colour-variant swap) naturally starts back at index 0
160	  // rather than carrying over a stale failure count from a completely different image set.
161	  const primaryCandidates = [primaryImage, ...(primaryImageFallbacks ?? [])];
162	  const [primaryCandidateIndex, setPrimaryCandidateIndex] = useState(0);
163	  const effectivePrimaryImage = primaryCandidates[Math.min(primaryCandidateIndex, primaryCandidates.length - 1)];
164	  const handlePrimaryImageError = () => {
165	    // Clamped, not unconditionally incremented: once every candidate has failed, this keeps
166	    // resolving to the same (still-broken) last one — same `Object.is`-equal bailout that stops
167	    // this from looping, and the same "no worse than before this prop existed" behaviour when
168	    // `primaryImageFallbacks` is empty/omitted (there is only ever one candidate to land on).
169	    setPrimaryCandidateIndex((index) => Math.min(index + 1, primaryCandidates.length - 1));
170	  };
171	
172	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
173	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
174	  const gallery = images && images.length > 1 ? images : undefined;
175	  const slideImages = gallery ?? [effectivePrimaryImage];
176	  const totalSlides = slideImages.length;
177	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
178	  const canPage = totalSlides > 1 && showControls;
179	  // Keyboard operability is independent of `showControls` — deliberately not folded into
180	  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
181	  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
182	  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
183	  // so this is the only paging affordance such a user has, regardless of `showControls`.
184	  const canNavigateByKeyboard = totalSlides > 1;
185	
186	  // Single piece of state, per this codebase's extract-to-hook threshold
187	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
188	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
189	  // because this build step's file manifest is limited to this component's own 4 files; a hook
190	  // would be a 5th file outside that scope.
191	  const [currentIndex, setCurrentIndex] = useState(0);
192	  const scrollContainerRef = useRef<HTMLDivElement>(null);
193	
194	  const scrollToIndex = (index: number) => {
195	    const container = scrollContainerRef.current;
196	    if (!container || typeof container.scrollTo !== 'function') return;
197	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
198	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
199	    // browser reports a real width so the requested slide scrolls fully into view.
200	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
201	  };
202	
203	  const goToRelativeSlide = (delta: 1 | -1) => {
204	    if (totalSlides <= 1) return;
205	    const next = (currentIndex + delta + totalSlides) % totalSlides;
206	    setCurrentIndex(next);
207	    scrollToIndex(next);
208	  };
209	
210	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
211	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
212	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
213	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
214	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
215	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
216	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
217	  useEffect(() => {
218	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
219	  }, [totalSlides]);
220	
221	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
222	  // capability — additive to, and independent of, the hover-capable-only arrows and the
223	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
224	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
225	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
226	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
227	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
228	    event.preventDefault();
229	    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
230	  };
231	
232	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
233	  // calls goToRelativeSlide at all. `scrollend` alone is not enough to do this live — that's
234	  // true on every browser, not just one lacking `scrollend` support: the event is only fired
