/** The correctly-sized product image view for gallery/hover/fallback purposes — never an
 *  arbitrary-sized image at thumbnail size (AGENTS.md's image-sizing guidance). Matches
 *  `recentlyViewedCard.ts`'s and `recentlyViewedFullHistoryCard.ts`'s own `MEDIUM_VIEW_TYPE`. */
const MEDIUM_VIEW_TYPE = 'medium';

/**
 * Resolves the ONE colour SFCC has already chosen to represent this hit — `hit.representedProduct`
 * is that decision (confirmed live, 2026-09-09: `representedProduct.id` always matches a real
 * entry in `hit.variants`), so this looks up that exact variant and reads its own
 * `variationValues.color`, rather than guessing at the hit's own top-level custom attributes
 * (`c_color`, unconfirmed/catalog-specific) or picking an arbitrary entry from `variationAttributes`
 * (which lists every available colour for the style, not which one this hit represents).
 *
 * Returns `undefined` when there's no `representedProduct`/matching variant at all (a hit with no
 * variants array, or a single-colour product where this resolution genuinely doesn't matter) —
 * callers degrade to an unscoped-by-colour lookup in that case, not a thrown error.
 */
export const resolveRepresentativeColour = (hit: ProductListSearchHit): string | undefined => {
  const representedId = hit.representedProduct?.id;
  if (!representedId) return undefined;

  const variant = hit.variants?.find((candidate) => candidate.productId === representedId);
  return variant?.variationValues?.[COLOUR_VARIATION_ATTRIBUTE_ID];
};

/**
 * The one real image lookup behind `selectGalleryImages`, `selectHoverImage` and
 * `selectPrimaryImageFallbacks` below — computed once here rather than three times, since all
 * three read the identical colour+viewtype-scoped set (conventions.md's DRY rule).
 *
 * **Closes a real, confirmed bug (2026-09-09), not a hypothetical.** The previous version of this
 * lookup (`selectGalleryImages`'s old "whichever image group has the most images" heuristic) had
 * no `viewType` filter and no colour filter at all — checked directly against a real two-colour
 * product (`ZWNEWPRD04`, BLK/TAN): its `imageGroups` carries separate, explicitly-tagged groups
 * per colour (`variationAttributes: [{id: 'color', values: [{value: 'BLK'}]}]` etc.), so "most
 * images" could freely pick the WRONG colour's photos, or a `large`/`small` group instead of
 * `medium` (confirmed on `4673TS251`, whose `large` group has 10 images against `medium`'s
 * correctly-scoped 9). Scoping to this hit's own SFCC-chosen colour, and to `medium` specifically
 * (the same correctly-sized view every other mapper in this codebase already standardises on),
 * closes both at once.
 *
 * **Fallback when colour can't be resolved:** still scope to `viewType: 'medium'` — never fall
 * all the way back to the old fully-unscoped behaviour, per this step's own build-plan pass
 * criteria.
 */
const resolveScopedMediumImages = (hit: ProductListSearchHit): ZimmProductCardImage[] => {
  const colour = resolveRepresentativeColour(hit);
  const filteredGroups = filterImageGroups(hit.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: colour ? { [COLOUR_VARIATION_ATTRIBUTE_ID]: colour } : {},
  }) as ShopperSearchTypes.ImageGroup[];

  const groupImages = filteredGroups[0]?.images ?? [];
  return groupImages.map(toCardImage).filter((img): img is ZimmProductCardImage => Boolean(img));
};

/**
 * This hit's gallery — the colour+viewtype-scoped image set from `resolveScopedMediumImages`
 * above. Returns `undefined` for 0 or 1 resulting images, matching `ZimmProductCardMedia`'s own
 * "no gallery" contract for that case — this function doesn't duplicate that check, it just never
 * returns a 1-length array.
 *
 * Signature/export unchanged from this function's previous version — only the internal
 * resolution changed (see `resolveScopedMediumImages`'s own docblock for what and why).
 */
export const selectGalleryImages = (hit: ProductListSearchHit): ZimmProductCardImage[] | undefined => {
  const images = resolveScopedMediumImages(hit);
  return images.length > 1 ? images : undefined;
};

/**
 * The second image in this hit's colour+viewtype-scoped set — what `ZimmProductCardMedia`
 * crossfades to on hover (`swapOnHover`/`hoverImage`, `VARIATION_CONFIG.plp.showHoverImageSwap`).
 * `undefined` when the scoped set has fewer than 2 images — no second photo, nothing to swap to.
 */
export const selectHoverImage = (hit: ProductListSearchHit): ZimmProductCardImage | undefined =>
  resolveScopedMediumImages(hit)[1];

/**
 * Backup candidates for `ZimmProductCardMedia`'s cascading `primaryImageFallbacks` — tried, in
 * order, only if this hit's own primary image (`hit.image`, SFCC's pre-selected "official" pick
 * for the configured search viewtype — confirmed via the SDK's own doc comment, 2026-09-09: "the
 * first image of the product hit for the configured viewtype", which can differ by product and by
 * available viewtype) fails to load. Deliberately the FULL scoped set, not `[1:]` — `hit.image`
 * resolves from a different, independent viewtype than `medium` (confirmed live: `4673TS251`'s
 * own official pick came from its `hi-res` group, not `medium`), so there's no overlap to exclude;
 * every image here is a genuinely different, valid backup candidate.
 */
export const selectPrimaryImageFallbacks = (hit: ProductListSearchHit): ZimmProductCardImage[] =>
  resolveScopedMediumImages(hit);

