// 2026-09-09 — mirrors the real ZWNEWPRD04 (BLK/TAN) shape confirmed live: `representedProduct`
// names the ONE variant SFCC has already chosen (BLK), `variants` carries each colour's own
// `variationValues.color`, and `imageGroups` carries separate, explicitly-tagged medium groups
// per colour. Deliberately constructed so "most images" (the old, wrong logic) and "correct
// colour" (the new, correct logic) disagree on every fixture below — the TAN group and the
// large group both have MORE images than the correct BLK group, so a regression back to the old
// heuristic would pick either of those instead and this test would catch it immediately.
const multiColourHit = {
  ...baseHit,
  representedProduct: { id: 'prod-1-BLK' },
  variants: [
    { productId: 'prod-1-BLK', variationValues: { color: 'BLK' } },
    { productId: 'prod-1-TAN', variationValues: { color: 'TAN' } },
  ],
  imageGroups: [
    {
      viewType: 'large',
      images: [{ link: 'large-1.jpg' }, { link: 'large-2.jpg' }, { link: 'large-3.jpg' }],
    },
    {
      viewType: 'medium',
      variationAttributes: [{ id: 'color', values: [{ value: 'TAN' }] }],
      images: [
        { link: 'tan-1.jpg', alt: 'Tan front' },
        { link: 'tan-2.jpg', alt: 'Tan back' },
        { link: 'tan-3.jpg', alt: 'Tan side' },
      ],
    },
    {
      viewType: 'medium',
      variationAttributes: [{ id: 'color', values: [{ value: 'BLK' }] }],
      images: [
        { link: 'blk-1.jpg', alt: 'Black front' },
        { link: 'blk-2.jpg', alt: 'Black back' },
      ],
    },
  ],
};

describe('resolveRepresentativeColour (2026-09-09, image-picking fix)', () => {
  test("resolves the colour of the variant matching representedProduct's own id", () => {
    expect(resolveRepresentativeColour(multiColourHit)).toBe('BLK');
  });

  test('returns undefined when there is no representedProduct at all', () => {
    expect(resolveRepresentativeColour({ ...baseHit, representedProduct: undefined })).toBeUndefined();
  });

  test('returns undefined when representedProduct.id matches no real variant', () => {
    const hit = { ...baseHit, representedProduct: { id: 'nonexistent' }, variants: multiColourHit.variants };
    expect(resolveRepresentativeColour(hit)).toBeUndefined();
  });
});

describe('selectGalleryImages', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...baseHit, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when every group has only 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        { viewType: 'small', images: [{ link: 'a.jpg' }] },
        { viewType: 'swatch', images: [{ link: 'b.jpg' }] },
      ],
    };
    expect(selectGalleryImages(hit)).toBeUndefined();
  });

  // Replaces the old "picks the image group with the most images" premise, which described
  // exactly the bug this fix closes (see multiColourHit's own comment above).
  test("picks the medium-viewtype group for the hit's own represented colour, even though both the large group and the wrong-colour medium group have more images", () => {
    expect(selectGalleryImages(multiColourHit)).toEqual([
      { src: 'blk-1.jpg', alt: 'Black front' },
      { src: 'blk-2.jpg', alt: 'Black back' },
    ]);
  });

  test('scopes to viewType "medium" even when colour cannot be resolved at all (single-colour hit, no representedProduct/variants)', () => {
    const singleColourHit = {
      ...baseHit,
      imageGroups: [
        {
          viewType: 'large',
          images: [{ link: 'large-1.jpg' }, { link: 'large-2.jpg' }, { link: 'large-3.jpg' }],
        },
        {
          viewType: 'medium',
          images: [{ link: 'medium-1.jpg', alt: 'Front' }, { link: 'medium-2.jpg', alt: 'Back' }],
        },
      ],
    };
    expect(selectGalleryImages(singleColourHit)).toEqual([
      { src: 'medium-1.jpg', alt: 'Front' },
      { src: 'medium-2.jpg', alt: 'Back' },
    ]);
  });
});

describe('selectHoverImage (2026-09-09, hover-swap fix)', () => {
  test('returns the second image in the colour+viewtype-scoped set', () => {
    expect(selectHoverImage(multiColourHit)).toEqual({ src: 'blk-2.jpg', alt: 'Black back' });
  });

  test('returns undefined when the scoped set has fewer than 2 images', () => {
    expect(selectHoverImage(baseHit)).toBeUndefined();
  });
});

describe('selectPrimaryImageFallbacks (2026-09-09, image-fallback fix)', () => {
  // Deliberately the FULL scoped set, not `[1:]` — see this function's own docblock for why
  // there's no overlap with the hit's own primary image (`hit.image`) to exclude.
  test('returns every image in the colour+viewtype-scoped set as a fallback candidate', () => {
    expect(selectPrimaryImageFallbacks(multiColourHit)).toEqual([
      { src: 'blk-1.jpg', alt: 'Black front' },
      { src: 'blk-2.jpg', alt: 'Black back' },
    ]);
  });

  test('returns an empty array, not undefined, when there are no usable images', () => {
    expect(selectPrimaryImageFallbacks(baseHit)).toEqual([]);
  });
});

