360	/**
361	 * Fix 1 (Scorer round 1, SFCC-236 Step 4 rework): the 19 tests above all render through the
362	 * `vi.mock('@chakra-ui/react', ...)` at the top of this file, which replaces useMultiStyleConfig
363	 * with a flat `{}` return for every part — none of them ever evaluate the REAL recipe object.
364	 * Proved live by the Scorer: deleting the recipe's HOVER_CAPABLE_QUERY media-query gate entirely
365	 * (making the desktop arrows permanently visible regardless of pointer capability) left the
366	 * whole suite green. These tests import the recipe module directly and call its exported
367	 * baseStyle(), bypassing the mock entirely — same technique as
368	 * zimmSizeChip.css.test.ts / zimmTextInput.css.test.ts.
369	 */
370	describe('ZimmProductCardMedia — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
371	  /**
372	   * Behavioural fix, confirmed against the Jira AC ("when on desktop and the user hovers, then
373	   * the arrows appear") and live Figma (Carousel is `hidden="true"` on every Default-state
374	   * instance checked, visible only on the matching Hover-state instance, for both PLP and
375	   * Wishlist). This test used to assert `carousel[HOVER_CAPABLE_QUERY].display === 'flex'` —
376	   * i.e. that ANY hover-capable device (not just an actually-hovering one) revealed the arrows
377	   * at THIS recipe's own level. That was the bug: a device-CAPABILITY check standing in for an
378	   * actual-hover check made the arrows permanently visible on desktop. The
379	   * `[HOVER_CAPABLE_QUERY]: { display: 'flex' }` sub-block that produced that value has been
380	   * removed from `carousel` entirely — the real hover/has(:focus-visible) reveal now lives one layer up,
381	   * on `ZimmProductCard`'s own organism recipe (`zimmProductCard.css.ts` docblock point 6),
382	   * scoped to the whole card via `&:hover`/`&:has(:focus-visible)`, which this Media-only recipe has no
383	   * visibility into (there is no composing organism root here to hover). See that file's own
384	   * "real recipe assertions" describe block for the reveal-rule regression guard.
385	   */
386	  test('carousel (arrows) has no reveal of its own at this recipe level — stays display:none unconditionally; indicatorWrapper is unaffected by the fix', () => {
387	    const style = ZimmProductCardMediaRecipe.baseStyle();
388	
389	    // Touch / non-hover-capable pointers (outside the media query): indicator visible, arrows
390	    // display:none. Fix J (SFCC-236) converted this part's unconditional hidden state from
391	    // `display: 'none'` to `clipPath: 'inset(50%)'` so the arrows would stay in the DOM/tab
392	    // order/accessibility tree even while clipped — Fix K (CodeRabbit finding on PR #85) reverted
393	    // that specifically here: this rule applies on EVERY pointer type, including touch, which
394	    // never enters the hover-capable reveal path at all (no `[HOVER_CAPABLE_QUERY]` key exists on
395	    // this part — see below), so clip-path left each arrow `<button>` permanently tabbable with no
396	    // way for a touch pointer to ever reveal it. Back to `display: 'none'` here; the hover-capable
397	    // override (where a reveal genuinely is possible) now lives on `zimmProductCard.css.ts`'s own
398	    // `[HOVER_CAPABLE_QUERY]` block instead (see that file's own Fix K note and "real recipe
399	    // assertions" describe block).
400	    expect(style.indicatorWrapper.display).toBe('block');
401	    expect(style.carousel.display).toBe('none');
402	    expect((style.carousel as Record<string, unknown>).clipPath).toBeUndefined();
403	
404	    // Hover-capable pointers: indicatorWrapper still hides itself via its own
405	    // `[HOVER_CAPABLE_QUERY]` key (unchanged by this fix) — but `carousel` still has no
406	    // `[HOVER_CAPABLE_QUERY]` key AT ALL at this recipe level (the hover-capable override now
407	    // lives on the organism instead). Regression guard: if a `[HOVER_CAPABLE_QUERY]` key ever
408	    // reappears here with an unconditional `display: 'flex'`, the permanent-visibility bug
409	    // (Fix J's own original motivation) is back.
410	    const carousel = style.carousel as Record<string, unknown>;
411	    const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
412	    expect(carousel[HOVER_CAPABLE_QUERY]).toBeUndefined();
413	    const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
414	    expect(indicatorHoverBlock.display).toBe('none');
415	  });
