478	  test('a real scrollend event with a simulated scroll position updates the indicator', () => {
479	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
480	    const container = screen.getByTestId('card-media-scroll');
481	
482	    // jsdom performs no real layout, so clientWidth/scrollWidth/scrollLeft all default to 0 —
483	    // but they ARE plain definable properties, so a real geometry can be simulated directly.
484	    // Slide width 300 x 3 slides, scrolled to slide index 1 (the 2nd of 3) => scrollLeft 300.
485	    const SIMULATED_SLIDE_WIDTH = 300;
486	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
487	    Object.defineProperty(container, 'scrollWidth', {
488	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
489	      configurable: true,
490	    });
491	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * 1, configurable: true });
492	
493	    // A raw `container.dispatchEvent(...)` bypasses @testing-library/react's configured
494	    // `eventWrapper`, so the resulting setCurrentIndex call is never flushed before the
495	    // assertion below runs. Routing the same native Event through RTL's generic `fireEvent`
496	    // call form (not one of its `fireEvent.<type>` convenience methods — `scrollend` isn't one
497	    // of those) dispatches the identical event while going through that act()-wrapping config.
498	    fireEvent(container, new Event('scrollend'));
499	
500	    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
501	  });
502	});
503	
504	/**
505	 * The `scrollend`-only tracking above lags for the whole duration of an active drag (it only
506	 * fires once the gesture settles) — confirmed live once a related fix made the swipe gesture
507	 * itself reachable for the first time. These tests cover the `scroll`-driven live-tracking path
508	 * added alongside it: see index.tsx's own updated comment above the effect for the full
509	 * reasoning. jsdom (this suite's Vitest environment) implements a real, timer-backed
510	 * `requestAnimationFrame`, so the throttled update is genuinely asynchronous here, not merely
511	 * simulated — the same real-rAF-plus-`waitFor` precedent already used by
512	 * list-menu-popover.test.tsx's own double-rAF-deferred assertions.
513	 */
514	describe('ZimmProductCardMedia — scroll listener drives the touch indicator live during an active drag', () => {
515	  const SIMULATED_SLIDE_WIDTH = 300;
516	
517	  /** Same "jsdom performs no real layout, but these are plain definable properties" approach as
518	   *  the `scrollend` test above — sets a plausible clientWidth/scrollWidth/scrollLeft for a
519	   *  given slide index directly. */
520	  const simulateScrollPosition = (container: HTMLElement, slideIndex: number) => {
521	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
522	    Object.defineProperty(container, 'scrollWidth', {
523	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
524	      configurable: true,
525	    });
526	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * slideIndex, configurable: true });
527	  };
528	
529	  test('a real scroll event with a simulated scroll position updates the indicator once the throttled animation frame runs', async () => {
530	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
531	    const container = screen.getByTestId('card-media-scroll');
532	    simulateScrollPosition(container, 1); // 2nd of 3 slides
533	
534	    // fireEvent (not a raw dispatchEvent) routes through RTL's act()-wrapping config, same
535	    // reasoning as the scrollend test above — necessary here too even though the resulting
536	    // setCurrentIndex call is additionally deferred behind a real requestAnimationFrame.
537	    fireEvent(container, new Event('scroll'));
538	
539	    // Unlike the scrollend path, this update is intentionally NOT synchronous — it is coalesced
540	    // behind a real requestAnimationFrame callback, so the assertion has to wait it out rather
541	    // than read the DOM immediately.
542	    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument());
543	  });
544	
545	  test('several scroll events fired before the pending animation frame runs are coalesced into a single requestAnimationFrame call, not one per event', async () => {
546	    // spyOn (no mockImplementation) still calls through to jsdom's real rAF — this only adds a
547	    // call-count tripwire on top of the real, unthrottled behavior it would otherwise have.
548	    const rafSpy = vi.spyOn(window, 'requestAnimationFrame');
549	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
550	    const container = screen.getByTestId('card-media-scroll');
551	    simulateScrollPosition(container, 1);
552	
553	    // Simulates the many `scroll` events a real touch-driven drag fires per second, all
554	    // dispatched before the browser has had any chance to run the first queued animation frame.
555	    fireEvent(container, new Event('scroll'));
556	    fireEvent(container, new Event('scroll'));
557	    fireEvent(container, new Event('scroll'));
558	
559	    // The `rafId !== null` guard means only the FIRST of the three calls above actually schedules
560	    // a frame — this is the throttling behavior itself, not merely "it eventually updates".
561	    expect(rafSpy).toHaveBeenCalledTimes(1);
562	
563	    // The position by the time the coalesced frame actually runs — proves the update reflects
564	    // the latest scroll position at that point, not whatever was current at the first event.
565	    simulateScrollPosition(container, 2);
566	    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument());
567	
568	    // Once that frame has run (clearing rafId back to null), a later scroll event schedules a
569	    // new one — the throttle resets every frame rather than firing only ever once.
570	    fireEvent(container, new Event('scroll'));
571	    expect(rafSpy).toHaveBeenCalledTimes(2);
572	
573	    rafSpy.mockRestore();
574	  });
575	});
576	
577	describe('ZimmProductCardMedia — scroll container is keyboard-operable regardless of pointer capability (Fix 5)', () => {
578	  test('ArrowRight/ArrowLeft on the scroll container wrap at both ends, the same as the visible arrows, even with showControls false', () => {
579	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls={false} />);
580	    const container = screen.getByTestId('card-media-scroll');
581	
582	    expect(container).toHaveAttribute('tabindex', '0');
583	
584	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 0 -> 1
585	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 1 -> 2 (last)
586	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
587	
588	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // wraps 2 -> 0
589	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
590	
591	    fireEvent.keyDown(container, { key: 'ArrowLeft' }); // wraps 0 -> 2 (last)
592	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
593	  });
594	
595	  test('the scroll container is not keyboard-focusable when there is only one image', () => {
596	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
597	    const container = screen.getByTestId('card-media-scroll');
598	    expect(container).not.toHaveAttribute('tabindex');
599	  });
600	});
