  test('hover-swap crossfade activates on the first slide even when a >1 image gallery is also active', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} images={GALLERY} swapOnHover showControls />);
    // 3 gallery slides, but slide 0 renders as a 2-image crossfade pair (its own gallery photo +
    // the hover image) instead of a single plain image: GALLERY[0] + HOVER + GALLERY[1] + GALLERY[2].
