    expect(screen.getByRole('img', { name: GALLERY[1].alt })).toBeInTheDocument();
    expect(screen.getByRole('img', { name: GALLERY[2].alt })).toBeInTheDocument();
  });

  test('the carousel arrows remain present and functional alongside the crossfade — the two are not mutually exclusive', async () => {
    const user = userEvent.setup();
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} images={GALLERY} swapOnHover showControls />);
    mockScrollTo();

    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.carousel}"]`)).toBeInTheDocument();
    const next = screen.getByRole('button', { name: 'Next image' });
