    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
  });

  test('the crossfade is confined to the first slide only — later gallery slides render as plain images', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} hoverImage={HOVER} images={GALLERY} swapOnHover showControls />);
    // data-role only ever appears on the crossfade pair (index.tsx's own hover-base/hover-overlay
