    expect(document.querySelectorAll('[data-role="hover-base"]')).toHaveLength(1);
    expect(document.querySelectorAll('[data-role="hover-overlay"]')).toHaveLength(1);
  });

  test('gallery fallback (primaryImageFallbacks) is still confined to the true primary slot and unaffected by the crossfade now combining with gallery mode', () => {
    const FALLBACK: ZimmProductCardMediaImage = { src: 'fallback.jpg', alt: 'Zimmermann dress, fallback' };
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        primaryImageFallbacks={[FALLBACK]}
        hoverImage={HOVER}
        images={GALLERY}
        swapOnHover
        showControls
      />,
    );
    fireEvent.error(screen.getByRole('img', { name: GALLERY[0].alt }));
    expect(screen.getByRole('img', { name: GALLERY[0].alt })).toBeInTheDocument();
    expect(screen.queryByRole('img', { name: FALLBACK.alt })).not.toBeInTheDocument();
  });
});

