import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });

await page.goto('http://localhost:3000/category/clothing', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(2000);

const checkProduct = async (productId, expectColourFragment, expectNotColourFragment) => {
  console.log(`\n=== ${productId} ===`);
  const card = page.locator(`[data-testid="product-card"][data-product-id="${productId}"]`);
  const count = await card.count();
  console.log('card found:', count > 0);
  if (count === 0) return;

  // C1 check: every rendered <img> src for this card must reflect the correct colour scoping.
  const imgSrcs = await card.locator('img').evaluateAll((imgs) => imgs.map((img) => img.getAttribute('src')));
  console.log('rendered img srcs:', JSON.stringify(imgSrcs, null, 2));
  if (expectNotColourFragment) {
    const leaked = imgSrcs.filter((src) => src && src.includes(expectNotColourFragment));
    console.log(`leaked "${expectNotColourFragment}" images:`, leaked.length === 0 ? 'NONE (correct)' : leaked);
  }
  if (expectColourFragment) {
    const matching = imgSrcs.filter((src) => src && src.includes(expectColourFragment));
    console.log(`images matching "${expectColourFragment}":`, matching.length);
  }

  // Pre-hover: hover-base should be opaque, hover-overlay transparent (if a crossfade pair exists)
  const hoverBase = card.locator('[data-role="hover-base"]');
  const hoverOverlay = card.locator('[data-role="hover-overlay"]');
  const hasCrossfade = (await hoverBase.count()) > 0;
  console.log('has hover-swap crossfade pair on slide 0:', hasCrossfade);

  if (hasCrossfade) {
    const beforeOverlayOpacity = await hoverOverlay.evaluate((el) => getComputedStyle(el).opacity);
    console.log('overlay opacity BEFORE hover:', beforeOverlayOpacity);
  }

  // C2 check: hover the card, confirm crossfade AND arrows fire together
  await card.hover();
  await page.waitForTimeout(400); // let the CSS opacity transition settle

  if (hasCrossfade) {
    const afterOverlayOpacity = await hoverOverlay.evaluate((el) => getComputedStyle(el).opacity);
    console.log('overlay opacity AFTER hover:', afterOverlayOpacity);
  }

  const carousel = card.locator(`[data-testid="card-media-scroll"]`).locator('..').locator('button', { hasText: '' });
  const arrowButtons = card.locator('[data-card-slot="carousel"] button');
  const arrowCount = await arrowButtons.count();
  let arrowVisibleAfterHover = false;
  if (arrowCount > 0) {
    const firstArrow = arrowButtons.first();
    const displayValue = await firstArrow.evaluate((el) => getComputedStyle(el).display);
    arrowVisibleAfterHover = displayValue !== 'none';
  }
  console.log('carousel arrow buttons found:', arrowCount, '| visible after hover:', arrowVisibleAfterHover);
};

await checkProduct('4673TS251', null, null);
await checkProduct('ZWNEWPRD04', 'BLK', 'TAN');

await browser.close();

