  const hoverBase = card.locator('[data-role="hover-base"]');
  const hoverOverlay = card.locator('[data-role="hover-overlay"]');
  const hasCrossfade = (await hoverBase.count()) > 0;
  console.log('has hover-swap crossfade pair on slide 0:', hasCrossfade);

  if (hasCrossfade) {
    const beforeOverlayOpacity = await hoverOverlay.evaluate((el) => getComputedStyle(el).opacity);
    console.log('overlay opacity BEFORE hover:', beforeOverlayOpacity);
  }

  // C2 check: hover the card, confirm crossfade AND arrows fire together
  await card.hover();
  await page.waitForTimeout(400); // let the CSS opacity transition settle

  if (hasCrossfade) {
    const afterOverlayOpacity = await hoverOverlay.evaluate((el) => getComputedStyle(el).opacity);
    console.log('overlay opacity AFTER hover:', afterOverlayOpacity);
  }

  const carousel = card.locator(`[data-testid="card-media-scroll"]`).locator('..').locator('button', { hasText: '' });
  const arrowButtons = card.locator('[data-card-slot="carousel"] button');
  const arrowCount = await arrowButtons.count();
  let arrowVisibleAfterHover = false;
  if (arrowCount > 0) {
    const firstArrow = arrowButtons.first();
    const displayValue = await firstArrow.evaluate((el) => getComputedStyle(el).display);
    arrowVisibleAfterHover = displayValue !== 'none';
  }
  console.log('carousel arrow buttons found:', arrowCount, '| visible after hover:', arrowVisibleAfterHover);
};

