import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });
await page.goto('http://localhost:3000/category/clothing', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(1500);

const chain = await page.evaluate(() => {
  const card = document.querySelector('[data-testid="product-card"]');
  const contentRoot = card.querySelector('[data-card-slot="content"]');
  const nameRow = contentRoot.firstElementChild;
  const nameLink = nameRow.firstElementChild;

  const walk = (el, label) => {
    const cs = getComputedStyle(el);
    return {
      label,
      tag: el.tagName,
      class: el.className,
      rectWidth: el.getBoundingClientRect().width,
      cssWidth: cs.width,
      display: cs.display,
      flex: cs.flex,
      flexBasis: cs.flexBasis,
      flexShrink: cs.flexShrink,
      flexGrow: cs.flexGrow,
      alignItems: cs.alignItems,
      boxSizing: cs.boxSizing,
      paddingLeft: cs.paddingLeft,
      paddingRight: cs.paddingRight,
    };
  };

  // Walk UP from card to find any ancestor narrower than expected, plus the whole card->nameLink chain
  const ancestors = [];
  let el = card;
  let depth = 0;
  while (el && depth < 8) {
    ancestors.push(walk(el, `ancestor-${depth}`));
    el = el.parentElement;
    depth++;
  }

  return {
    ancestors,
    card: walk(card, 'card'),
    contentRoot: walk(contentRoot, 'contentRoot'),
    nameRow: walk(nameRow, 'nameRow'),
    nameLink: walk(nameLink, 'nameLink'),
    nameRowSiblings: Array.from(contentRoot.children).map((c, i) => walk(c, `contentRoot-child-${i}`)),
  };
});
console.log(JSON.stringify(chain, null, 2));

await browser.close();

