 * the resolved colour above. `colour` undefined (see `resolveRepresentativeColour`'s own
 * doc for when) degrades to a viewtype-only lookup — still better than no scoping at all, never
 * the fully-unscoped "any colour, any viewtype" behaviour this replaces.
 */
const selectColourScopedImages = (hit: ProductListSearchHit, colour: string | undefined): ZimmProductCardImage[] => {
  const filteredGroups = filterImageGroups(hit.imageGroups ?? [], {
    viewType: MEDIUM_VIEW_TYPE,
    variationValues: colour ? { [COLOUR_VARIATION_ATTRIBUTE_ID]: colour } : {},
  }) as ImageGroupShape[];

