describe('ZimmProductCardMedia — primaryImageFallbacks (live defect: a broken catalog image can sit ahead of working ones)', () => {
  const FALLBACK_1: ZimmProductCardMediaImage = { src: 'fallback-1.jpg', alt: 'Zimmermann dress, alternate angle' };
  const FALLBACK_2: ZimmProductCardMediaImage = { src: 'fallback-2.jpg', alt: 'Zimmermann dress, another angle' };

  test('swaps to the first fallback candidate once the primary image fails to load', () => {
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        primaryImageFallbacks={[FALLBACK_1, FALLBACK_2]}
        swapOnHover={false}
        showControls={false}
      />,
    );
    const img = screen.getByRole('img', { name: PRIMARY.alt });
    expect(img).toHaveAttribute('src', PRIMARY.src);

    fireEvent.error(img);

    const swapped = screen.getByRole('img', { name: FALLBACK_1.alt });
    expect(swapped).toHaveAttribute('src', FALLBACK_1.src);
    expect(screen.queryByRole('img', { name: PRIMARY.alt })).not.toBeInTheDocument();
  });

  test('keeps cascading through every candidate in order if more than one fails', () => {
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        primaryImageFallbacks={[FALLBACK_1, FALLBACK_2]}
        swapOnHover={false}
        showControls={false}
      />,
    );
    fireEvent.error(screen.getByRole('img', { name: PRIMARY.alt }));
    fireEvent.error(screen.getByRole('img', { name: FALLBACK_1.alt }));

    expect(screen.getByRole('img', { name: FALLBACK_2.alt })).toHaveAttribute('src', FALLBACK_2.src);
  });

  test('stays on the last candidate, without looping or crashing, once every candidate has failed', () => {
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        primaryImageFallbacks={[FALLBACK_1]}
        swapOnHover={false}
        showControls={false}
      />,
    );
    fireEvent.error(screen.getByRole('img', { name: PRIMARY.alt }));
    const lastCandidate = screen.getByRole('img', { name: FALLBACK_1.alt });
    fireEvent.error(lastCandidate);
    fireEvent.error(lastCandidate);

    expect(screen.getByRole('img', { name: FALLBACK_1.alt })).toHaveAttribute('src', FALLBACK_1.src);
  });

  test('a primary image error with no primaryImageFallbacks supplied is a no-op — same behaviour as before this prop existed', () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
    const img = screen.getByRole('img', { name: PRIMARY.alt });
    fireEvent.error(img);
    expect(screen.getByRole('img', { name: PRIMARY.alt })).toHaveAttribute('src', PRIMARY.src);
  });

  test('has no effect once a real multi-image gallery is active — the fallback is scoped to the primary slot only', () => {
    wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        primaryImageFallbacks={[FALLBACK_1]}
        images={GALLERY}
        swapOnHover={false}
        showControls
      />,
    );
    // slideImages[0] here is GALLERY[0], not PRIMARY — erroring it must never pull in a
    // primaryImageFallbacks candidate that has nothing to do with this gallery.
    fireEvent.error(screen.getByRole('img', { name: GALLERY[0].alt }));
    expect(screen.getByRole('img', { name: GALLERY[0].alt })).toHaveAttribute('src', GALLERY[0].src);
    expect(screen.queryByRole('img', { name: FALLBACK_1.alt })).not.toBeInTheDocument();
  });
});

