import { chromium } from 'playwright';

const PRODUCT_ID = 'ZWNEWPRD04';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 1400 } });

await page.goto('http://localhost:3000/category/clothing', { waitUntil: 'load', timeout: 30000 });
await page.waitForTimeout(3000);

const card = page.locator(`[data-testid="product-card"][data-product-id="${PRODUCT_ID}"]`);
const cardCount = await card.count();
console.log('card found on /category/clothing:', cardCount > 0);

if (cardCount === 0) {
  console.log('Card not found - cannot verify.');
  await browser.close();
  process.exit(1);
}

// Raw SSR check first: confirm which colour is representative, and what the resolved medium
// group actually contains, independent of what renders.
const raw = await page.evaluate((pid) => {
  const scripts = Array.from(document.querySelectorAll('script'));
  for (const s of scripts) {
    const text = s.textContent ?? '';
    const idx = text.indexOf(`"productId":"${pid}"`);
    if (idx === -1) continue;
    return text.slice(idx, idx + 400);
  }
  return null;
}, PRODUCT_ID);
console.log('\nRaw SSR snippet (productId onward):\n', raw);

// Hover the card and inspect the rendered <img> tags before/after.
const imgSrcsBefore = await card.locator('img').evaluateAll((imgs) => imgs.map((i) => i.getAttribute('src')));
console.log('\n<img> srcs BEFORE hover:', imgSrcsBefore);

await card.hover();
await page.waitForTimeout(400);

const imgSrcsAfter = await card.locator('img').evaluateAll((imgs) => imgs.map((i) => i.getAttribute('src')));
console.log('<img> srcs AFTER hover:', imgSrcsAfter);

// Confirm every rendered gallery/hover src belongs to the same colour (BLK), not a TAN mix-in.
const anyTan = imgSrcsAfter.some((src) => src && src.toUpperCase().includes('TAN'));
const anyBlk = imgSrcsAfter.some((src) => src && src.toUpperCase().includes('BLK'));
console.log('\nAny TAN image present (should be false):', anyTan);
console.log('Any BLK image present (should be true):', anyBlk);

await browser.close();

