import { chromium } from 'playwright';

// Fresh, isolated context — no cache, no cookies, nothing carried over from any prior run.
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 1400 } });
const page = await context.newPage();

await page.goto('http://localhost:3000/category/clothing', { waitUntil: 'load', timeout: 30000 });

const card = page.locator('[data-testid="product-card"][data-product-id="4673TS251"]');
await card.waitFor({ state: 'attached', timeout: 10000 });

// Check IMMEDIATELY, no artificial grace period — exactly what a real user's first paint shows.
const immediate = await card.locator('img').evaluateAll((els) =>
  els.map((el) => ({ src: el.getAttribute('src').slice(-40), complete: el.complete, naturalWidth: el.naturalWidth })),
);
console.log('=== immediately after load event (no wait) ===');
console.log(JSON.stringify(immediate, null, 2));

// Now wait and check again to see if/when it settles.
for (const delay of [500, 1500, 3000]) {
  await page.waitForTimeout(delay);
  const snapshot = await card.locator('img').evaluateAll((els) =>
    els.map((el) => ({ src: el.getAttribute('src').slice(-40), complete: el.complete, naturalWidth: el.naturalWidth })),
  );
  console.log(`\n=== after +${delay}ms more ===`);
  console.log(JSON.stringify(snapshot, null, 2));
}

// Take a real screenshot too, for a definitive visual check.
await card.screenshot({ path: '/tmp/4673-card-check.png' });
console.log('\nScreenshot saved to /tmp/4673-card-check.png');

await browser.close();
