cat > .tmp-confirm-bm-fix.mjs << 'SCRIPT'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 1400 }, bypassCSP: true });
const page = await context.newPage();
// Cache-bust to make sure we're not looking at anything stale from earlier runs.
await page.goto(`http://localhost:3000/category/clothing?cb=${Date.now()}`, { waitUntil: 'load', timeout: 30000 });

const card = page.locator('[data-testid="product-card"][data-product-id="4673TS251"]');
await card.waitFor({ state: 'attached', timeout: 10000 });

// Check immediately (no grace period) — exactly what a real first-time visitor sees.
const immediate = await card.locator('img').evaluateAll((els) =>
  els.map((el) => ({ src: el.getAttribute('src'), complete: el.complete, naturalWidth: el.naturalWidth, role: el.getAttribute('data-role') })),
);
console.log('=== immediately on load ===');
console.log(JSON.stringify(immediate, null, 2));

// Confirm again after a delay, to make sure nothing regresses/changes (i.e. no fallback engaging).
await page.waitForTimeout(2000);
const settled = await card.locator('img').evaluateAll((els) =>
  els.map((el) => ({ src: el.getAttribute('src'), naturalWidth: el.naturalWidth, role: el.getAttribute('data-role') })),
);
console.log('\n=== after 2s (should be identical — no fallback engaging) ===');
console.log(JSON.stringify(settled, null, 2));

// Direct fetch of the raw medium-viewtype URL itself, independent of the rendered card.
const rawUrl = immediate[0]?.src;
if (rawUrl) {
  const resp = await page.request.get(rawUrl);
  console.log('\nDirect fetch of the medium image URL itself:', rawUrl);
  console.log('HTTP status:', resp.status());
}

await browser.close();
