cat > .tmp-verify-sort-fix.mjs << 'SCRIPT'
import { chromium } from 'playwright';

const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1280, height: 1400 } });
const page = await context.newPage();
await page.goto(`http://localhost:3000/category/clothing?cb=${Date.now()}`, { waitUntil: 'load', timeout: 30000 });

const card = page.locator('[data-testid="product-card"][data-product-id="4673TS251"]');
await card.waitFor({ state: 'attached', timeout: 10000 });

const imgs = await card.locator('img').evaluateAll((els) =>
  els.map((el) => ({ src: el.getAttribute('src'), role: el.getAttribute('data-role') })),
);

const hoverBase = imgs.find((i) => i.role === 'hover-base');
const hoverOverlay = imgs.find((i) => i.role === 'hover-overlay');
console.log('Primary (hover-base) src ends with:', hoverBase?.src.split('/').pop());
console.log('Hover (hover-overlay) src ends with:', hoverOverlay?.src.split('/').pop());
console.log('\nExpected: primary should be image "1" (flat-lay), hover should be image "2" (on-model).');

await browser.close();
SCRIPT
node .tmp-verify-sort-fix.mjs 2>&1
rm -f .tmp-verify-sort-fix.mjs

