1	/**
2	 * Ties the plain Commerce API product shape (`recentlyViewedProductFetch.ts`'s own `getProducts`
3	 * result) to the rendered `plp`-variation `ZimmProductCard` props, the same "G1" doctrine
4	 * `recentlyViewedCard.test.ts`/`productInfo.test.ts` document: every assertion below uses a value
5	 * unique to its own field (the 'large' image group's `alt` is deliberately a value that must never
6	 * be picked) so a mapping that reads the wrong key fails rather than coincidentally matching.
7	 *
8	 * **Was/Now made to fail on purpose first, per this codebase's own established discipline** (see
9	 * `recentlyViewedCard.test.ts`'s own docblock and the build plan's A4 pass criteria for the same
10	 * rule stated elsewhere): while authoring the tests below, `selectPriceFields`'s `isOnSale` guard
11	 * in `recentlyViewedFullHistoryCard.ts` was temporarily inverted (`!priceData.isOnSale &&` in
12	 * place of `priceData.isOnSale &&`) and the suite re-run — the "on-sale" test failed by asserting
13	 * `originalPrice` was `undefined` when it should have been `'AUD 650.00'`, and the "not-on-sale"
14	 * test failed by asserting a defined `originalPrice` when it should have been `undefined`. Both
15	 * failed exactly as expected, confirming the assertions actually exercise the guard rather than
16	 * passing regardless of it. The inversion was then reverted and the suite re-run to confirm a
17	 * clean pass — see the implementation report for the real terminal output of both runs.
18	 */
19	import { describe, expect, test, vi } from 'vitest';
20	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
21	import {
22	  selectRecentlyViewedFullHistoryCard,
23	  selectGalleryImages,
24	  selectSizeChipValues,
25	  resolveOrderableVariant,
26	  type FormatPrice,
27	  type RecentlyViewedFullHistoryProduct,
28	} from './recentlyViewedFullHistoryCard';
