30	const formatPrice: FormatPrice = (amount, currency) => `${currency} ${amount.toFixed(2)}`;
31	
32	// On sale: two tiered prices (500, 650) with no promotions -- getPriceData's own findLowestPrice
33	// resolves currentPrice to the base 500 (no promotion beats it), and listPrice to the higher
34	// tiered price, 650, so isOnSale (500 < 650) is true. Verified independently against a real
35	// getPriceData call below, not just hand-computed here.
36	const ON_SALE: RecentlyViewedFullHistoryProduct = {
37	  id: 'FH-PRODUCT-ID-0001',
38	  name: 'Natura Mini Dress',
39	  currency: 'AUD',
40	  price: 500,
41	  tieredPrices: [
42	    { price: 500, quantity: 1 },
43	    { price: 650, quantity: 1 },
44	  ],
45	  imageGroups: [
46	    {
47	      viewType: 'medium',
48	      images: [
49	        {
