51	          disBaseLink: 'https://cdn.example.test/medium/natura-mini-dress.jpg',
52	          alt: 'Natura Mini Dress, Ivory',
53	        },
54	      ],
55	    },
56	    {
57	      // Wrong viewType -- must never be picked for primaryImage. If it is, the alt assertion
58	      // below fails.
59	      viewType: 'large',
60	      images: [
61	        {
62	          link: 'https://example.test/large/natura-mini-dress.jpg',
63	          alt: 'WRONG VIEWTYPE -- MUST NOT BE PICKED FOR PRIMARY',
64	        },
65	      ],
66	    },
67	  ],
68	  variationAttributes: [
69	    {
70	      id: 'size',
71	      name: 'Size',
72	      values: [
73	        { value: 'xs', name: 'XS', orderable: true },
74	        { value: 's', name: 'S', orderable: false },
