/**
 * Broken-image fallback cascade (2026-09-08 build) — `primaryImage` fails to load, and this
 * component advances through `primaryImageFallbacks` in order until one succeeds. Two broken
 * candidates in a row before a working one, deliberately — proves the cascade genuinely loops
 * past more than one failure rather than only handling a single retry.
 *
 * `BROKEN_IMAGE` is a real, unresolvable URL (RFC 2606's reserved `.invalid` TLD) rather than a
 * `data:` URI — a `data:` URI can never fail to load, so it cannot exercise `onError` at all. This
 * means the browser genuinely attempts and fails a real network request, the same real event the
 * cascade responds to in production. No `play` function — same manual-visual-check convention
 * this file already uses for every other network/timing-dependent story (`MultipleImages`'s own
 * hover-arrow reveal, for the same reason): expect a brief broken-image flash before the fallback
 * resolves, timing dependent on how quickly the browser gives up on each unresolvable host.
 */
export const WithBrokenImageFallback: Story = {
  name: 'Broken-image fallback cascade',
  args: {
    primaryImage: BROKEN_IMAGE,
    primaryImageFallbacks: [BROKEN_IMAGE, PRIMARY_IMAGE],
    swapOnHover: false,
    showControls: false,
  },
};

