python3 -c "
import re, json

with open('$CLAUDE_JOB_DIR/tmp/cat_product-badges_recheck.html') as f:
    text = f.read()
m = re.search(r'<script id=\"mobify-data\" type=\"application/json\">(.*?)</script>', text, re.S)
data = json.loads(m.group(1))

def find_hit(obj, target_id, seen=None):
    if seen is None:
        seen = set()
    if id(obj) in seen:
        return None
    if isinstance(obj, dict):
        seen.add(id(obj))
        if obj.get('productId') == target_id:
            return obj
        for v in obj.values():
            r = find_hit(v, target_id, seen)
            if r: return r
    elif isinstance(obj, list):
        for v in obj:
            r = find_hit(v, target_id, seen)
            if r: return r
    return None

hit = find_hit(data, '4673TS251')
if hit:
    print('hit keys:', sorted(hit.keys()))
    print('c_productBadges present?', 'c_productBadges' in hit)
    for k in hit.keys():
        if k.startswith('c_') or 'custom' in k.lower():
            print(' custom field:', k, '=', hit[k])
else:
    print('hit not found')
"

python3 -c "
import re, json, glob

def find_all_hits(obj, results, seen):
    if isinstance(obj, dict):
        if 'productId' in obj and obj.get('productId') not in seen:
            seen.add(obj.get('productId'))
            results.append(obj)
        for v in obj.values():
            find_all_hits(v, results, seen)
    elif isinstance(obj, list):
        for v in obj:
            find_all_hits(v, results, seen)

all_hits = []
seen = set()
for path in glob.glob('$CLAUDE_JOB_DIR/tmp/cat_*.html'):
    with open(path) as f:
        text = f.read()
    m = re.search(r'<script id=\"mobify-data\" type=\"application/json\">(.*?)</script>', text, re.S)
    if not m:
        continue
    data = json.loads(m.group(1))
    find_all_hits(data, all_hits, seen)

print('total distinct hits checked:', len(all_hits))
any_custom = 0
for h in all_hits:
    custom_keys = [k for k in h.keys() if k.startswith('c_')]
    if custom_keys:
        any_custom += 1
        print(' -', h.get('productId'), 'custom keys:', custom_keys)
print('hits with ANY c_ field at all:', any_custom, 'out of', len(all_hits))
"

