import { chromium } from '@playwright/test';

const BASE = 'http://localhost:3000';
const RAIL_SELECTOR = '[data-testid="recently-viewed-rail"]';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

// Seed history: view two real products so the rail has something to show.
await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'networkidle' });
await page.waitForTimeout(500);
await page.goto(`${BASE}/product/8637DS241`, { waitUntil: 'networkidle' });
await page.waitForTimeout(500);

const checks = [
  { name: 'pdp', url: `${BASE}/product/4673TS251` },
  { name: 'plp', url: `${BASE}/category/clothing` },
  { name: 'cart', url: `${BASE}/cart` },
];

for (const { name, url } of checks) {
  await page.goto(url, { waitUntil: 'networkidle' });
  const rail = page.locator(RAIL_SELECTOR).first();
  const count = await rail.count();
  if (count === 0) {
    console.log(`${name}: NO RAIL FOUND at ${url}`);
