import { chromium } from '@playwright/test';

const BASE = 'http://localhost:3000';
const RAIL_SELECTOR = '[data-testid="recently-viewed-rail"]';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });

// Seed history: view two real products so the rail has something to show.
await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);
await page.goto(`${BASE}/product/8637DS241`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);

const checks = [
  { name: 'pdp', url: `${BASE}/product/4673TS251` },
  { name: 'plp', url: `${BASE}/category/clothing` },
  { name: 'cart', url: `${BASE}/cart` },
];

for (const { name, url } of checks) {
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(1200);
  const rail = page.locator(RAIL_SELECTOR).first();
  const count = await rail.count();
  console.log(`${name}: rail count = ${count}`);
  if (count > 0) {
    const box = await rail.boundingBox();
    console.log(`${name}: rail bounding box`, box);
    await page.evaluate((selector) => {
      const el = document.querySelector(selector);
      if (el) {
        const rect = el.getBoundingClientRect();
        window.scrollTo(0, window.scrollY + rect.top - 120);
      }
    }, RAIL_SELECTOR);
    await page.waitForTimeout(400);
  } else {
    // Log some page content to understand why -- e.g. is the cart empty?
    const bodyText = await page.locator('body').innerText();
    console.log(`${name}: no rail — first 300 chars of body text:`, bodyText.slice(0, 300).replace(/\n/g, ' | '));
  }
  await page.screenshot({ path: `${process.env.CLAUDE_JOB_DIR}/tmp/live_full_${name}.png` });
}

await browser.close();

