import { chromium } from '@playwright/test';

const BASE = 'http://localhost:3000';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });

await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);
await page.goto(`${BASE}/product/8637DS241`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);
await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);

const info = await page.evaluate(() => {
  const rail = document.querySelector('[data-testid="recently-viewed-rail"]');
  if (!rail) return { found: false };
  const railRect = rail.getBoundingClientRect();
  const railStyle = getComputedStyle(rail);
  const children = Array.from(rail.children).map((child) => {
    const rect = child.getBoundingClientRect();
    const style = getComputedStyle(child);
    return {
      tag: child.tagName,
      testid: child.getAttribute('data-testid'),
      text: child.textContent?.slice(0, 100),
      rect: { x: rect.x, y: rect.y, width: rect.width, height: rect.height },
      display: style.display,
      background: style.backgroundColor,
      visibility: style.visibility,
      opacity: style.opacity,
    };
  });
  return {
    found: true,
    railRect: { x: railRect.x, y: railRect.y, width: railRect.width, height: railRect.height },
    railBackground: railStyle.backgroundColor,
    children,
  };
});

console.log(JSON.stringify(info, null, 2));

await browser.close();

