const info = await page.evaluate(() => {
  const rail = document.querySelector('[data-testid="recently-viewed-rail"]');
  if (!rail) return { found: false };
  const headerDiv = rail.children[0];
  const walk = (el, depth) => {
    if (!el || depth > 4) return null;
    const rect = el.getBoundingClientRect();
    const style = getComputedStyle(el);
    return {
      tag: el.tagName,
      ownText: el.childNodes.length && el.childNodes[0].nodeType === 3 ? el.childNodes[0].textContent : null,
      rect: { x: Math.round(rect.x), y: Math.round(rect.y), width: Math.round(rect.width), height: Math.round(rect.height) },
      color: style.color,
      fontSize: style.fontSize,
      textTransform: style.textTransform,
      display: style.display,
      children: Array.from(el.children).map((c) => walk(c, depth + 1)),
    };
  };
  return { found: true, header: walk(headerDiv, 0) };
});

console.log(JSON.stringify(info, null, 2));

await browser.close();

