import { chromium } from '@playwright/test';

const BASE = 'http://localhost:3000';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });

await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);
await page.goto(`${BASE}/product/8637DS241`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);
await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);

const pdpChain = await page.evaluate(() => {
  let el = document.querySelector('[data-testid="recently-viewed-rail"]');
  const chain = [];
  while (el) {
    const style = getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    chain.push({
      tag: el.tagName,
      className: typeof el.className === 'string' ? el.className.slice(0, 80) : null,
      testid: el.getAttribute('data-testid'),
      paddingLeft: style.paddingLeft,
      marginLeft: style.marginLeft,
      width: Math.round(rect.width),
      left: Math.round(rect.x),
    });
    el = el.parentElement;
  }
  return chain;
});

console.log('=== PDP ancestor chain (rail -> html) ===');
console.log(JSON.stringify(pdpChain, null, 2));

await page.goto(`${BASE}/category/clothing`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);

const plpChain = await page.evaluate(() => {
  let el = document.querySelector('[data-testid="recently-viewed-rail"]');
  const chain = [];
  while (el) {
    const style = getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    chain.push({
      tag: el.tagName,
      className: typeof el.className === 'string' ? el.className.slice(0, 80) : null,
      testid: el.getAttribute('data-testid'),
      paddingLeft: style.paddingLeft,
      marginLeft: style.marginLeft,
      width: Math.round(rect.width),
      left: Math.round(rect.x),
    });
    el = el.parentElement;
  }
  return chain;
});

console.log('=== PLP ancestor chain (rail -> html) ===');
console.log(JSON.stringify(plpChain, null, 2));

await browser.close();

