import { chromium } from '@playwright/test';

const BASE = 'http://localhost:3000';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });

const measure = async (label) => {
  const info = await page.evaluate(() => {
    const results = {};
    // Header: find the real nav/logo row content, not just the outer <header> shell.
    const header = document.querySelector('header');
    if (header) {
      const rect = header.getBoundingClientRect();
      results.headerOuter = { x: Math.round(rect.x), width: Math.round(rect.width) };
      // First element with real visible content inside header (e.g. logo or nav links row)
      const firstContentRow = header.querySelector('a, nav, [class*="css-"]');
      if (firstContentRow) {
        const r2 = firstContentRow.getBoundingClientRect();
        results.headerFirstContentRow = {
          tag: firstContentRow.tagName,
          x: Math.round(r2.x),
          width: Math.round(r2.width),
        };
      }
      // Look specifically for nav link items (e.g. "CLOTHING") to get real content edge
      const links = Array.from(header.querySelectorAll('a')).filter((a) => a.textContent?.trim().length > 0);
      if (links.length > 0) {
        const firstLink = links[0].getBoundingClientRect();
        const lastLink = links[links.length - 1].getBoundingClientRect();
        results.headerFirstLinkX = Math.round(firstLink.x);
        results.headerLastLinkRight = Math.round(lastLink.x + lastLink.width);
      }
    }
    const footer = document.querySelector('footer');
    if (footer) {
      const rect = footer.getBoundingClientRect();
      results.footerOuter = { x: Math.round(rect.x), width: Math.round(rect.width) };
      const links = Array.from(footer.querySelectorAll('a')).filter((a) => a.textContent?.trim().length > 0);
      if (links.length > 0) {
        const firstLink = links[0].getBoundingClientRect();
        results.footerFirstLinkX = Math.round(firstLink.x);
      }
      // Footer's own background band -- how wide is the actual coloured/bg element?
      const bgCandidate = footer.firstElementChild;
      if (bgCandidate) {
        const r3 = bgCandidate.getBoundingClientRect();
        const style = getComputedStyle(bgCandidate);
        results.footerBgBand = { x: Math.round(r3.x), width: Math.round(r3.width), bg: style.backgroundColor };
      }
    }
    results.viewportWidth = window.innerWidth;
    return results;
  });
  console.log(`=== ${label} ===`);
  console.log(JSON.stringify(info, null, 2));
};

await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);
await measure('PDP');

await page.goto(`${BASE}/category/clothing`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);
await measure('PLP');

await browser.close();

