import { chromium } from '@playwright/test';

const BASE = 'http://localhost:3000';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });

await page.goto(`${BASE}/product/4673TS251`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);
await page.goto(`${BASE}/product/8637DS241`, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1200);

for (const { name, url } of [
  { name: 'pdp', url: `${BASE}/product/4673TS251` },
  { name: 'plp', url: `${BASE}/category/clothing` },
]) {
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(1000);
  const box = await page.locator('[data-testid="recently-viewed-rail"]').first().boundingBox();
  console.log(`${name}:`, box);
}

await browser.close();

