const imgProduct = "https://www.figma.com/api/mcp/asset/39af48b3-0d20-4c40-94d5-bdea29d69603.png";

type LinkProps = {
  className?: string;
  label?: string;
  size?: "Large";
  state?: "default";
};

function Link({ className, label = "Label", size = "Large", state = "default" }: LinkProps) {
