const card = {
    py: 6,
    px: 4,
    backgroundColor: 'white',
    rounded: 'base',
    boxShadow: 'base'
}

const cardBordered = {
    ...card,
    px: [4, 4, 5, 6],
    border: '1px solid',
    borderColor: 'gray.50'
}

export default {
    card,

    cardBordered,

    ccIcon: {
        width: '34px',
        height: '22px'
    },

    page: {
        px: [4, 4, 6, 6, 8],
        paddingTop: [4, 4, 6, 6, 8],
        paddingBottom: 32,
        width: '100%',
        maxWidth: 'container.xxxl',
        marginLeft: 'auto',
        marginRight: 'auto'
    }
}

// Spacing scale — source of truth: Figma node 2081:52901 (Design-Workspace > Spacing)
// Added to theme.space via extendTheme — Chakra's numeric defaults are preserved.
// Values are in rem so spacing scales with a user's root font-size / browser zoom
// (WCAG 1.4.4). Border widths (below) intentionally stay in px: hairline geometry
// shouldn't scale with zoom.

// prettier-ignore
export const spacing = {
  '3xs': '0.125rem', // 2px
  '2xs': '0.25rem',  // 4px
  xs:    '0.5rem',   // 8px
  s:     '0.75rem',  // 12px
  m:     '1rem',     // 16px
  l:     '1.25rem',  // 20px
  xl:    '1.5rem',   // 24px
  '2xl': '2rem',     // 32px
  '3xl': '2.5rem',   // 40px
  '4xl': '4rem',     // 64px
  '5xl': '5rem',     // 80px
  '6xl': '8rem',     // 128px
  '7xl': '10rem',    // 160px
} as const;

// Border widths — source of truth: Handover tokens/spacing.css (--zimm-border-width-default).
// Registered as theme.borderWidths; the CSS-var twin already exists in zimmTokens.ts.
export const borderWidths = {
  default: '1px',
} as const;

// Focus-ring outline offsets — hairline geometry, stays px like border widths above.
// `secondary` clears the 1px border on the secondary button variant (Handover
// button.md §focus) — the name describes that variant, not a generic scale step,
// since nothing else currently needs a third offset value.
export const focusRingOffsets = {
  default: '2px',
  secondary: '3px',
} as const;

input.old_string:
// Fixed 2026-09-10, closing a real, live-confirmed bug (Figma-vs-build audit, Marcel): the
// negative-margin trick that lets a `RecommendedProducts` rail bleed edge-to-edge inside a
// `layerStyle="page"` container (PDP's Complete-the-Set/Might-Also-Like/Recently-Viewed, PLP's
// Recently-Viewed) previously used plain Chakra numeric spacing (`{base: -4, md: -8, lg: 0}`,
// i.e. -16px/-32px/0) with no relationship at all to this site's own real page padding. That real
// padding lives in exactly one place, `theme/foundation/gridSystem.ts`'s own `grid.containerPadding`
// (32px through just under 1280px, 40px from 1280px up) — the previous value cancelled only half
// of it on mobile (-16px against a real 32px, leaving the rail visibly inset by 16px instead of
// flush) and dropped to zero 288px too early (Chakra's `lg` step, 992px, a full 288px before this
// site's own real desktop breakpoint at 1280px). Derived directly from the same registered
// `--zimm-grid-margin-*` tokens `gridSystem.ts` itself is built from (see that file's own
// docblock), not re-typed by hand, so the two can never drift apart again. Only two real steps,
// matching `gridSystem.ts`'s own two real breakpoints (mobile+tablet share one value; only
// desktop differs) — `md`/`lg` are deliberately not separate keys here, since the underlying
// padding doesn't actually change at either of those.
export const PAGE_CONTENT_BLEED_MX = {
  base: 'calc(var(--zimm-grid-margin-mobile) * -1)',
  xl: 0,
} as const;

input.new_string:
// Fixed 2026-09-10, closing a real, live-confirmed bug (Figma-vs-build audit, Marcel) — REVISED
// same day after the first attempt below turned out to cancel the wrong padding source. First
// attempt's premise: the negative-margin trick that lets a `RecommendedProducts` rail bleed
// edge-to-edge previously used plain Chakra numeric spacing (`{base: -4, md: -8, lg: 0}`) with no
// relationship to this site's page padding, so it was repointed at `gridSystem.ts`'s
// `--zimm-grid-margin-*` tokens (32/32/32/32/40px) instead. That premise was wrong: the Rail
// doesn't actually sit inside `gridSystem.ts`'s grid container — that scale is for header/footer
// only (see that file's own docblock claim, which is aspirational, not universal). The Rail sits
// inside PDP's `<PageContainer boxed={true}>` and PLP's root `<Box layerStyle="page">`, and both
// of those resolve to a completely different, un-migrated base-SFCC padding scale — confirmed
// byte-identical in `pageContainer/index.tsx`'s own `paddingXValue` and the vendor's own
// `layerStyles.js`: `px: [4, 4, 6, 6, 8]` (base/sm/md/lg/xl → 16/16/24/24/32px). Cancelling
// against the grid-margin tokens instead left every breakpoint mismatched (e.g. -32px applied
// against only 16px of real ambient padding at `base`) and skipped the real scale's middle step
// entirely (md/lg genuinely differs from base/sm, at 24px vs 16px — the two-key `{base, xl}` shape
// had no way to express that third value).
//
// Corrected value: `[4, 4, 6, 6, 8]` in Chakra's stock numeric scale is exactly `[m, m, xl, xl,
// 2xl]` in Zimmermann's own named scale (`spacing.ts`: m=16px, xl=24px, 2xl=32px) — so this now
// cancels `--zimm-scale-m`/`-xl`/`-2xl` (already-registered tokens, not re-typed numbers) instead
// of the grid-margin vars. Three breakpoint keys, matching where the real scale actually steps —
// `base` covers base+sm (both 16px), `md` covers md+lg (both 24px), `xl` is its own step (32px).
export const PAGE_CONTENT_BLEED_MX = {
  base: 'calc(var(--zimm-scale-m) * -1)',
  md: 'calc(var(--zimm-scale-xl) * -1)',
  xl: 'calc(var(--zimm-scale-2xl) * -1)',
} as const;

