// flush) and dropped to zero 288px too early (Chakra's `lg` step, 992px, a full 288px before this
// site's own real desktop breakpoint at 1280px). Derived directly from the same registered
// `--zimm-grid-margin-*` tokens `gridSystem.ts` itself is built from (see that file's own
// docblock), not re-typed by hand, so the two can never drift apart again. Only two real steps,
// matching `gridSystem.ts`'s own two real breakpoints (mobile+tablet share one value; only
// desktop differs) — `md`/`lg` are deliberately not separate keys here, since the underlying
// padding doesn't actually change at either of those.
export const PAGE_CONTENT_BLEED_MX = {
  base: 'calc(var(--zimm-grid-margin-mobile) * -1)',
  xl: 0,
} as const;

