146	/**
147	 * Quick test integration only (SFCC-83/84) — swaps the base `ProductTile` for the shared
148	 * `ZimmProductCard` (`variation: 'plp'`) so it can be exercised against a real PLP grid. Not the
149	 * final PLP implementation: it still needs the "product card group" component this grid doesn't
150	 * have yet. Owns its own `selectedSizeChipValue` local state — same pattern
151	 * `organisms/zimmProductCard/index.stories.tsx`'s own `LiveSizeSelectionCard` already uses —
152	 * since the page renders many of these and this can't be a single page-level state variable.
153	 *
154	 * **Also resolves the real orderable variant for Add to Bag (2026-09-08, Gap 3 fix).** This is
155	 * the one component that ever knows which size is currently selected — `handleAddToBag` below is
156	 * built in the parent's render loop, with no access to this component's own local state, so
157	 * variant resolution has to happen here, not there. `hit` and `onResolvedAddToBag` are this
158	 * component's own props (not part of `ZimmProductCardProps` at all — `ZimmProductCard` itself
159	 * still only ever receives a plain, no-argument `onAddToBag`, matching its existing, unchanged
160	 * contract for every variation).
161	 */
162	type ProductListCardProps = Extract<ZimmProductCardProps, { variation: 'plp' }> & {
163	  hit: ProductListSearchHit;
164	  onResolvedAddToBag: (productId: string, price: number | undefined) => void;
165	};
166	
167	const ProductListCard = ({ hit, onResolvedAddToBag, ...cardProps }: ProductListCardProps) => {
168	  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(
169	    () => cardProps.selectedSizeChipValue,
170	  );
171	  const handleSizeChipSelect = (value: string) => {
172	    setSelectedSizeChipValue(value);
173	    cardProps.onSizeChipSelect?.(value);
174	  };
175	  const handleAddToBag = () => {
176	    // No selection -> today's existing default-variant behaviour, unchanged (no size selected
177	    // means default size). A selection that somehow matches no real
178	    // variant falls back the same way, rather than blocking the add entirely on a data mismatch.
179	    const resolved = selectedSizeChipValue ? resolveOrderableVariant(hit, selectedSizeChipValue) : null;
180	    const orderableProductId = resolved?.productId ?? hit.representedProduct?.id ?? hit.productId;
181	    onResolvedAddToBag(orderableProductId, resolved?.price ?? hit.price);
182	  };
183	
184	  return (
185	    <ZimmProductCard
186	      {...cardProps}
187	      selectedSizeChipValue={selectedSizeChipValue}
188	      onSizeChipSelect={handleSizeChipSelect}
189	      onAddToBag={handleAddToBag}
190	    />
191	  );
192	};
