194	/*
195	 * This is a simple product listing page. It displays a paginated list
196	 * of product hit objects. Allowing for sorting and filtering based on the
197	 * allowable filters and sort refinements.
198	 */
199	const ProductList = (props: ProductListProps) => {
200	  // Using destructuring to omit properties; we must rename `isLoading` because we use a different
201	  // `isLoading` later in this function.
202	  const { isLoading: _unusedIsLoading, staticContext: _unusedStaticContext, ...rest } = props;
203	  const { isOpen, onOpen, onClose } = useDisclosure();
204	  // `intl.formatMessage`/`intl.formatNumber`, never a destructured `{ formatMessage }`: the
205	  // base file's own original destructure tripped `@typescript-eslint/unbound-method` (the
206	  // established fix already used elsewhere in this codebase — see
207	  // zimmProductStyleCode/index.tsx) — consolidated to the one `intl` object throughout.
208	  const intl = useIntl();
209	  const navigate = useNavigation();
210	  const buildUrl = useSafeHref();
211	  const history = useHistory();
212	  const params = useParams<{ categoryId?: string }>();
213	  const location = useLocation();
214	  const toast = useToast();
215	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
216	  // Passed into the card mapper rather than formatted there — keeps that mapper a pure function
217	  // with no react-intl dependency of its own, same split its own docblock documents.
218	  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });
219	  const einstein = useEinstein();
220	  const dataCloud = useDataCloud();
221	  const activeData = useActiveData();
222	  const { res } = useServerContext();
223	  const customerId = useCustomerId();
224	  const [searchParams, { stringify: stringifySearchParams }] = useSearchParams();
225	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
226	
227	  /**************** Page State ****************/
228	  const [filtersLoading, setFiltersLoading] = useState(false);
229	  const [wishlistLoading, setWishlistLoading] = useState<string[]>([]);
230	  const [sortOpen, setSortOpen] = useState(false);
231	  const [searchByInventory, setSearchByInventory] = useState<string | number | null>(null);
232	
233	  const urlParams = new URLSearchParams(location.search);
234	  const searchQuery = urlParams.get('q');
235	  const isSearch = !!searchQuery;
236	
237	  if (params.categoryId) {
238	    searchParams._refine.push(`cgid=${params.categoryId}`);
239	  }
240	
241	  /**************** Mutation Actions ****************/
242	  const { mutateAsync: createCustomerProductListItem } = useShopperCustomersMutation('createCustomerProductListItem');
243	  const { mutateAsync: deleteCustomerProductListItem } = useShopperCustomersMutation('deleteCustomerProductListItem');
244	
245	  /**************** Query Actions ****************/
246	  // _refine is an invalid param for useProductSearch, we don't want to pass it to API call
247	  const { _refine, ...restOfParams } = searchParams;
248	
249	  const refine = searchByInventory ? [..._refine, `ilids=${searchByInventory}`] : _refine;
250	
251	  const {
252	    isLoading,
253	    isFetched,
254	    isRefetching,
255	    data: productSearchResult,
256	  } = useProductSearch(
257	    {
258	      parameters: {
259	        ...restOfParams,
260	        perPricebook: true,
261	        allVariationProperties: true,
262	        allImages: true,
263	        expand: [
264	          'promotions',
265	          'variations',
266	          'prices',
267	          'images',
268	          'page_meta_tags',
269	          'custom_properties',
270	          'availability',
271	          'represented_products',
272	        ],
273	        refine,
274	      },
275	    },
276	    {
277	      keepPreviousData: true,
278	    },
279	  );
280	
281	  const { error, data: category } = useCategory(
282	    {
283	      parameters: {
284	        // `enabled` below gates the actual request on a real categoryId; the fallback here only
285	        // satisfies the hook's own parameter type (which does not accept `undefined`) for the
286	        // render where categoryId isn't present yet (e.g. a search-query route).
287	        id: params.categoryId ?? '',
288	      },
289	    },
290	    {
291	      enabled: !isSearch && !!params.categoryId,
292	    },
293	  );
294	
295	  // Apply disallow list to refinements.
296	  if (productSearchResult?.refinements) {
297	    productSearchResult.refinements = productSearchResult.refinements.filter(
298	      ({ attributeId }) => !REFINEMENT_DISALLOW_LIST.includes(attributeId),
299	    );
300	  }
301	
302	  /**************** Error Handling ****************/
303	  const errorStatus = (error as { response?: { status?: number } } | null)?.response?.status;
304	  switch (errorStatus) {
305	    case undefined:
306	      // No Error.
307	      break;
308	    case 404:
309	      throw new HTTPNotFound('Category Not Found.');
310	    default:
311	      throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
312	  }
313	
314	  /**************** Response Handling ****************/
315	  if (res) {
316	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
317	  }
318	
319	  // Reset scroll position when `isRefetching` becomes `true`.
320	  useEffect(() => {
321	    isRefetching && window.scrollTo(0, 0);
322	    setFiltersLoading(isRefetching);
323	  }, [isRefetching]);
324	
325	  /**************** Render Variables ****************/
326	  const basePath = `${location.pathname}${location.search}`;
327	  const showNoResults = !isLoading && productSearchResult && !productSearchResult?.hits;
328	  const { total, sortingOptions } = productSearchResult || {};
329	  const selectedSortingOptionLabel =
330	    sortingOptions?.find((option) => option.id === productSearchResult?.selectedSortingOption) ?? sortingOptions?.[0];
331	
332	  // Get urls to be used for pagination, page size changes, and sorting.
333	  const pageUrls = usePageUrls({ total });
334	  const sortUrls = useSortUrls({ options: sortingOptions });
335	  const limitUrls = useLimitUrls();
336	
337	  /**************** Action Handlers ****************/
338	  const { data: wishlist } = useWishList();
339	  const addItemToWishlist = async (product: { productId: string }) => {
340	    setWishlistLoading([...wishlistLoading, product.productId]);
341	
342	    // TODO: This wishlist object is from an old API, we need to replace it with the new one.
343	    // `wishlist!`/`customerId!`: this handler only runs from a click on a tile's own wishlist
344	    // toggle, which is only reachable once the page's data has loaded — the original untyped
345	    // JS made the identical assumption implicitly (an undefined `wishlist` here would have
346	    // thrown the same way at runtime); the assertion just makes that pre-existing assumption
347	    // visible instead of introducing a new one.
348	    const listId = wishlist.id;
349	    await createCustomerProductListItem(
350	      {
351	        parameters: { customerId: customerId!, listId },
352	        body: {
353	          quantity: 1,
354	          public: false,
355	          priority: 1,
356	          type: 'product',
357	          productId: product.productId,
358	        },
359	      },
360	      {
361	        onError: () => {
362	          toast({
363	            title: intl.formatMessage(API_ERROR_MESSAGE),
364	            status: 'error',
365	          });
366	        },
367	        onSuccess: () => {
368	          toast({
369	            title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
370	            status: 'success',
371	            action: (
372	              // it would be better if we could use <Button as={Link}>
373	              // but unfortunately the Link component is not compatible
374	              // with Chakra Toast, since the ToastManager is rendered via portal
375	              // and the toast doesn't have access to intl provider, which is a
376	              // requirement of the Link component.
377	              <Button variant="link" onClick={() => navigate('/account/wishlist')}>
378	                {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
379	              </Button>
380	            ),
381	          });
382	        },
383	        onSettled: () => {
384	          setWishlistLoading(wishlistLoading.filter((id) => id !== product.productId));
385	        },
386	      },
387	    );
388	  };
389	
390	  const removeItemFromWishlist = async (product: { productId: string }) => {
391	    setWishlistLoading([...wishlistLoading, product.productId]);
392	
393	    // Same reasoning as addItemToWishlist above: only reachable once wishlist data has loaded,
394	    // matching what the original untyped JS already assumed implicitly.
395	    const listId = wishlist.id;
396	    const itemId = wishlist.customerProductListItems!.find(
397	      (i: { productId: string }) => i.productId === product.productId,
398	    )!.id;
399	
400	    await deleteCustomerProductListItem(
401	      {
402	        // No `body` field: the real mutation type has none for a delete, and an empty object
403	        // was never meaningful at runtime either.
404	        parameters: { customerId: customerId!, listId, itemId },
405	      },
406	      {
407	        onError: () => {
408	          toast({
409	            title: intl.formatMessage(API_ERROR_MESSAGE),
410	            status: 'error',
411	          });
412	        },
413	        onSuccess: () => {
414	          toast({
415	            title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
416	            status: 'success',
417	          });
418	        },
419	        onSettled: () => {
420	          setWishlistLoading(wishlistLoading.filter((id) => id !== product.productId));
421	        },
422	      },
423	    );
424	  };
425	
426	  // Toggles filter on and off
427	  const toggleFilter = (
428	    value: { value: string | number },
429	    attributeId: string,
430	    selected: boolean,
431	    allowMultiple = true,
432	  ) => {
433	    // Special handling for inventory filter
434	    if (attributeId === 'ilids') {
435	      if (!selected) {
436	        setSearchByInventory(value.value);
437	      } else {
438	        setSearchByInventory(null);
439	      }
440	      return;
441	    }
442	
443	    const searchParamsCopy = { ...searchParams };
444	
445	    // Remove the `offset` search param if present.
446	    delete searchParamsCopy.offset;
447	
448	    // If we aren't allowing for multiple selections, simply clear any value set for the
449	    // attribute, and apply a new one if required.
450	    if (!allowMultiple) {
451	      const previousValue = searchParamsCopy.refine[attributeId];
452	      delete searchParamsCopy.refine[attributeId];
453	
454	      // Note the loose comparison, for "string != number" checks.
455	      if (!selected && value.value != previousValue) {
456	        searchParamsCopy.refine[attributeId] = value.value;
457	      }
458	    } else {
459	      // Get the attibute value as an array.
460	      let attributeValue = searchParamsCopy.refine[attributeId] || [];
461	
462	      // Ensure that the value is still converted into an array if it's a `string` or `number`.
463	      if (typeof attributeValue === 'string') {
464	        attributeValue = attributeValue.split('|');
465	      } else if (typeof attributeValue === 'number') {
