// required, not the base path, per overrideStyling.md's "importing an already-overridden
// component from a new component" rule.
import { HideOnDesktop } from '../../components/responsive';
// Same rule as HideOnDesktop above — recommended-products is already overridden in this repo,
// and this file is itself an override, so a base-path import here would never be redirected by
// the webpack resolver at all (isFromExtends returns false for an issuer inside overrides/); it
// would silently load the real, un-overridden base component instead. Relative path required.
