/*
 * Copy-first port of
 * node_modules/@salesforce/retail-react-app/app/components/recommended-products/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
 *
 * The differences from the base file are the TypeScript annotations below and house
 * formatting — no changed JSX, hook calls, prop names, or reordered `useEffect`s, and the base
 * file's own dead check (`recommendations.length < 1` on what is always an object) is ported
 * byte-identical in behaviour. The annotations: a `RecommendedProductsProps` type replacing the
 * `propTypes` block; a narrow local `RecommendedProduct` type for the one field read off a
 * recommendation-context product (reused for the `productTileProps` callback's own `product`
 * param below, since it is that same recommendation-context product); an explicit `boolean`
 * param on the one nested callback that isn't contextually typed; and inline
 * `{ productId?: string }` / `{ id?: string }` object-type-literal params on four
 * `.find`/`.some`/`.map` callbacks whose containing expression is untyped (`any`) and therefore
 * supplies no contextual parameter type — `noImplicitAny` flags these regardless of the `any`
 * receiver (confirmed against `npx tsc --noEmit`, which is why these four are annotated despite
 * this file's own initial plan expecting two of them not to need it). The `{ productId?: string
 * }` shape and inline-annotation style mirrors the existing precedent at
 * product-detail/index.tsx:437 and :735; the `{ id?: string }` shape matches the field the base
 * hook itself reads, `use-einstein.js`'s own `reco.recs?.map((rec) => rec.id)` (line 466).
 *
 * A sixth adjustment, found by lint rather than tsc: the base file destructures `formatMessage`
 * straight off `useIntl()`, but `@typescript-eslint/unbound-method` flags any destructured
 * reference to it — `formatMessage` is declared with method-shorthand syntax in
 * `@formatjs/intl/src/types.d.ts:64-65`, which this rule always flags regardless of whether the
 * real implementation needs `this`. Fix: keep the whole object (`const intl = useIntl();`) and
 * call `intl.formatMessage(...)` at each of its five call sites instead of destructuring — a
 * property-access call sidesteps the rule entirely, with zero behavioural change. Same
 * "toolchain requires a different access shape than the untyped base file used" reasoning as the
 * annotations above.
 *
 * SFCC-83/84 build plan step A6 adds one branch: when `recommender ===
 * EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED` (`'viewed-recently-einstein'`, the same string
 * `CART_RECENTLY_VIEWED` resolves to — confirmed identical in
 * node_modules/@salesforce/retail-react-app/app/constants.js:154-160), this component renders
 * `ZimmRecentlyViewedRail` instead of `ProductScroller`, gated by `useRecentlyViewedHistory`'s
 * `hasRecentlyViewed` (overrides/app/hooks/useRecentlyViewedHistory.ts). Every other recommender
 * keeps the original `ProductScroller` branch below, untouched.
 *
 * **Revised 2026-09-08, build plan §2 "Interim data source" (Einstein confirmed "Not Deployed" on
 * every real Zimmermann site) — supersedes the original 2026-09-07 A6 draft, not merely extends
 * it.** That draft mapped Einstein's own `recommendations.recs` through `selectRecentlyViewedCard`
 * directly and gated on `useRecentlyViewedGate`'s plain boolean. This branch now instead reads
 * `recentlyViewedIds` off `useRecentlyViewedHistory` (renamed from `useRecentlyViewedGate`,
 * extended to also track ids) and fetches real product data for them via
 * `useRecentlyViewedProductFetch` (overrides/app/utils/recentlyViewedProductFetch.ts) before
 * mapping through the same (revised) `selectRecentlyViewedCard` — `recommendations.recs` is never
 * read for this one branch, at all. Three consequences fall out of that switch, each fixed here
 * rather than carried forward as a latent bug:
 * 1. The `getRecommendations`/`getZoneRecommendations` effect below now returns early for this one
 *    recommender — calling either would fire a real Einstein request whose response this branch
 *    no longer consumes.
 * 2. Because that effect never runs for this recommender, `useEinstein()`'s own `recommendations`
 *    state never leaves its `useState([])` initial value
 *    (node_modules/@salesforce/retail-react-app/app/hooks/use-einstein.js:462-463) for this
 *    branch — which would make the pre-existing dead-check below evaluate `true` unconditionally
 *    (via its `recommendations.length < 1` clause specifically, since `recommendations` itself
 *    stays a truthy `[]`, never falsy) and return `null` regardless of `hasRecentlyViewed`. Fixed
 *    by moving this whole branch ahead of that check — see the comment there. Every other
 *    recommender is unaffected by the reordering.
 * 3. `sendViewReco`/`sendClickReco`/`dataCloud.sendViewRecommendations` are Einstein's own
 *    impression/click analytics, keyed by a real `recoUUID` from an actual `getRecommendations`
 *    response — with none for this branch, the existing `isOnScreen && recommendations?.recs`
 *    effect below correctly no-ops for it on its own (`recommendations` stays `[]`, so `.recs` is
 *    `undefined`); no separate code change was needed there, only confirmation. Accepted,
 *    temporary analytics gap on this one branch, stated in the PR body, not a silent regression.
 *
 * `ref` is still attached on the Recently Viewed branch too, via a plain wrapping `<Box
 * ref={ref}>` — `isOnScreen` below (the impression-tracking gate for `sendViewReco`/
 * `dataCloud.sendViewRecommendations`) only works once `ref.current` is a real DOM node
 * (use-intersection-observer.js: `if (!ref?.current) return`, with no dependency on which
 * component produced that node), and `ZimmRecentlyViewedRail` is a plain function component with
 * no `forwardRef` support of its own. Wrapping here, rather than adding `forwardRef` to that
 * already-committed component (A5), keeps this fix entirely inside this file.
 *
 * `headingLevel`/`variation` are added here, not by the mapper: `selectRecentlyViewedCard`'s own
 * docblock states both are deliberately excluded from its output because they are this
 * container's decision to make. `headingLevel: 'h3'` is inert for this variation —
 * `ZimmProductCardContent` never mounts when `variation: 'recentlyViewed'`
 * (zimmProductCard/index.tsx's `VARIATION_CONFIG.showContent`) — and matches the one other
 * established value for this same required field (product-list/productListCardMapper.ts).
 *
 * `{...props}` is forwarded to the `<Box>` wrapper (cast to `BoxProps` — this file's own index
 * signature types `props` as `Record<string, unknown>`, not safely spreadable onto `Box`'s typed
 * props otherwise), matching the ProductScroller branch below exactly. This matters concretely:
 * PDP passes `mx={{base: -4, md: -8, lg: 0}}` and Cart passes `mx={{base: -4, sm: -6, lg: 0}}` to
 * bleed this component edge-to-edge on mobile/tablet — without forwarding it, this branch would
 * render inset inside the page's normal content padding while every sibling rail on the same page
 * bleeds to the edge, and `zimmRecentlyViewedRail.css.ts`'s own card-width math (e.g. 201x2=402)
 * assumes the full viewport width is actually available. Confirmed live on PDP/Cart/PLP,
 * 2026-09-08 (a real Playwright session against the running app, real view history, real
 * screenshots) — this genuinely renders edge-to-edge on all three surfaces.
 *
 * **The See-Full-History link, added 2026-09-08 — previously a stated "not yet built" gap on
 * every caller.** `seeAllHref`/`seeAllLabel` are computed here, once, rather than by
 * each page: `showSeeAllLink` compares this branch's own unsliced `cards.length` against
 * `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS` (app/constants — 2/3/5 per breakpoint) resolved via
 * `useBreakpointValue`, matching the AC's own "exceeds the visible rail width" wording, which is
 * viewport-relative, not a flat count (Open Question 1, reopened 2026-09-07 after the original
 * flat->5 reading was found to misread that AC text). No ResizeObserver — `useBreakpointValue`
 * reads the current breakpoint only. `seeAllHref` is site/locale-prefixed via `useMultiSite`'s own
 * `buildUrl` — this container builds the prefix, never the rail itself (AGENTS.md's Multi-site
 * section: never assume routing). `title`, by contrast, stays each caller's own responsibility
 * (PDP/Cart/PLP each pass their own) — a correction from an earlier instruction to one caller
 * (PLP) that wrongly deferred `title` to this same "not yet built" step alongside the link; fixed
 * there and noted here so the split doesn't get re-confused later.
 */

import React, { useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { useLocation } from 'react-router-dom';
import { defineMessages, useIntl } from 'react-intl';
import { useBreakpointValue } from '@chakra-ui/react';
import type { BoxProps } from '@chakra-ui/react';
import { Box, Button } from '@salesforce/retail-react-app/app/components/shared/ui';
import ProductScroller from '@salesforce/retail-react-app/app/components/product-scroller';
import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';

import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
import {
  API_ERROR_MESSAGE,
  EINSTEIN_RECOMMENDERS,
  TOAST_ACTION_VIEW_WISHLIST,
  TOAST_MESSAGE_ADDED_TO_WISHLIST,
  TOAST_MESSAGE_REMOVED_FROM_WISHLIST,
} from '@salesforce/retail-react-app/app/constants';
// Zimmermann's own constants — NOT the base package above. RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS/
// RECENTLY_VIEWED_ROUTE only exist here; importing them from the base package instead compiles
// (that module has no real type declarations, so any named import type-checks as `any`) but is
// `undefined` at runtime — confirmed the hard way via a failing test before this was split out.
import { RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS, RECENTLY_VIEWED_ROUTE } from 'app/constants';
import { useShopperCustomersMutation } from '@salesforce/commerce-sdk-react';
// Relative, not the base package path — .claude/rules/overrideStyling.md's "Importing an
// already-overridden component from a new component": .storybook/main.js and vitest.config.ts
// don't load the overrides resolver, so a base-path import here would silently story/test the
// unstyled base component instead of this override.
import { ZimmRecentlyViewedRail } from '../ui-kits/organisms/zimmRecentlyViewedRail';
import type { ZimmProductCardProps } from '../ui-kits/organisms/zimmProductCard';
import { selectRecentlyViewedCard } from '../../utils/recentlyViewedCard';
import type { RecentlyViewedCard } from '../../utils/recentlyViewedCard';
import { useRecentlyViewedHistory } from '../../hooks/useRecentlyViewedHistory';
import { useRecentlyViewedProductFetch } from '../../utils/recentlyViewedProductFetch';

/**
 * The See-Full-History link's own accessible label. Not in this file's existing message set (it
 * had none before this step) because nothing here owned any copy of its own until now — `title`
 * has always been each caller's own responsibility (see the Recently-Viewed branch below), and
 * this is the one piece of copy this container itself needs.
 */
const messages = defineMessages({
  seeFullHistory: {
    id: 'recommended_products.link.see_full_history',
    defaultMessage: 'See Full History',
  },
});

/**
 * The one field this file reads off a recommendation-context product. A real
 * commerce-sdk-isomorphic Product shape underlies it, but @salesforce/retail-react-app's
 * useEinstein/ProductScroller ship untyped (vendor.d.ts's wildcard), so this is narrowed
 * to exactly the field touched here rather than invented more broadly (AGENTS.md > Type
 * Definitions: hand-roll only the genuinely unexported shape actually used).
 */
type RecommendedProduct = { productId?: string };

/**
 * Stable empty-id-list reference passed to `useRecentlyViewedProductFetch` for every recommender
 * except Recently-Viewed itself (see the hook call below) — an inline `[]` literal would behave
 * identically (`cappedIds.length > 0` is `false` either way, per
 * recentlyViewedProductFetch.ts's own `enabled` check), but a module-level constant avoids
 * allocating a fresh array on every render for no reason. Same naming/intent as
 * `useRecentlyViewedHistory.ts`'s own `EMPTY_IDS`
 * (overrides/app/hooks/useRecentlyViewedHistory.ts:18).
 */
const NO_RECENTLY_VIEWED_IDS: readonly string[] = [];

export type RecommendedProductsProps = {
  /* The title to appear above the product scroller */
  title?: ReactNode;

  /* The zone to request */
  zone?: string;

  /* The recommender to request */
  recommender?: string;

  /* The products to use for recommendation context */
  products?: readonly Record<string, unknown>[];

  /* Callback to determine if the component should fetch results */
  shouldFetch?: () => boolean;

  // Index signature for the `...props` passthrough to ProductScroller (itself untyped — see
  // vendor.d.ts). Without it, the destructured rest types as `{}` instead of accepting arbitrary
  // passthrough, which is the base file's actual intent: forwarding whatever else the caller
  // passes.
  [key: string]: unknown;
};

/**
 * A component for fetching and rendering product recommendations from the Einstein API
 * by a zone or a recommender name.
 */
const RecommendedProducts = ({
  zone,
  recommender,
  products,
  title,
  shouldFetch,
  ...props
}: RecommendedProductsProps) => {
  const { isLoading, recommendations, getZoneRecommendations, getRecommendations, sendClickReco, sendViewReco } =
    useEinstein();
  const { data: customer } = useCurrentCustomer();
  const { customerId } = customer;
  const { data: wishlist } = useWishList();
  const dataCloud = useDataCloud();

  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
  const deleteCustomerProductListItem = useShopperCustomersMutation('deleteCustomerProductListItem');
  const toast = useToast();
  const navigate = useNavigation();
  const intl = useIntl();
  // Same split product-list/productListCardMapper.ts's own consumer uses
  // (product-list/index.tsx): passed into the mapper rather than formatted there, keeping that
  // mapper free of any react-intl dependency of its own.
  const formatPrice = (amount: number, currency: string) => intl.formatNumber(amount, { style: 'currency', currency });

  const ref = useRef();
  const isOnScreen = useIntersectionObserver(ref, { useOnce: true });
  const [_products, setProducts] = useState(products);
  // Cart-exclusion check (2026-09-10, Marcel: "no recently viewed on cart" — a standing product
  // decision, not an Einstein-not-deployed-yet placeholder). Cart has no Zimmermann override
  // (no overrides/app/pages/cart/ at all) — its base page imports this same overridden component
  // and passes `recommender={EINSTEIN_RECOMMENDERS.CART_RECENTLY_VIEWED}`, which resolves to the
  // exact same string as PDP_RECENTLY_VIEWED (confirmed identical,
  // node_modules/.../constants.js:154-160), so the recommender check below cannot tell the two
  // apart by value alone. `.endsWith('/cart')`, not an exact match — AGENTS.md's Multi-site
  // section: a real storefront path is locale/site-prefixed (e.g. `/en-GB/cart`), so an exact
  // `=== '/cart'` would only ever match the default site.
  const location = useLocation();
  const isCartPage = location.pathname.endsWith('/cart');
  // Unconditional, alongside the hook calls above — must run on every render, including the
  // ones that hit the dead-code early returns further below, per React's rules of hooks.
  const { hasRecentlyViewed, recentlyViewedIds } = useRecentlyViewedHistory();
  // The See-Full-History trigger threshold, resolved for whichever breakpoint is actually
  // current. Also unconditional per rules of hooks; only meaningful inside the Recently-Viewed
  // branch below, same as the two hooks immediately above. `useBreakpointValue` reads the current
  // breakpoint only — no ResizeObserver, no runtime DOM measurement, matching the AC's own
  // viewport-relative "exceeds the visible rail width" wording (Open Question 1).
  const visibleCardCount =
    useBreakpointValue(RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS) ?? RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base;
  // `buildUrl` site/locale-prefixes an internal path (e.g. `/en-GB/recently-viewed` on a non-AU
  // storefront) — AGENTS.md's Multi-site section: never assume routing. The rail itself must not
  // build this prefix; this container does it once, here.
  const { buildUrl } = useMultiSite();
  // Also unconditional, same rules-of-hooks reason — but only ever given this shopper's real
  // tracked ids (and therefore only ever allowed to fire its own `getProducts` request, per its
  // own `enabled: cappedIds.length > 0`) when this particular instance is actually the
  // Recently-Viewed branch below. Every other recommender rendered on the same page (e.g. PDP's
  // own Might-Also-Like rail, mounted right alongside this one) would otherwise silently trigger
  // a second, unread product fetch whenever this browser already has tracked view history — the
  // same "network call fetching data nothing will ever read" problem fixed for
  // getRecommendations/getZoneRecommendations below, applied here to the fetch this branch adds.
  // `!isCartPage` too — see that constant's own comment above; Cart never renders this branch's
  // output, so fetching real product data for it there would be pure waste.
  const { products: recentlyViewedProducts } = useRecentlyViewedProductFetch(
    recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED && !isCartPage
      ? recentlyViewedIds
      : NO_RECENTLY_VIEWED_IDS,
  );

  useEffect(() => {
    // SFCC-83/84 build plan A6, bug fix #2 (2026-09-08 revision) — Recently Viewed no longer
    // reads Einstein's `recommendations` at all (see the branch further below), so calling
    // `getRecommendations`/`getZoneRecommendations` for it would be a real network request
    // fetching a response nothing ever reads. Skip both below for this one recommender; every
    // other recommender's fetch is unaffected.
    if (recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED) {
      return;
    }

    // Check if the component should fetch results or not. This is useful
    // when you are still waiting on additional data, like `products`.
    if (typeof shouldFetch === 'function' && !shouldFetch()) {
      return;
    }

    // Fetch either zone or recommender, but not both. If a zone and recommender
    // name are both provided, `zone` takes precendence.
    if (zone) {
      getZoneRecommendations(zone, _products);
      return;
    }
    if (recommender) {
      getRecommendations(recommender, _products);
      return;
    }
  }, [zone, recommender, _products]);

  useEffect(() => {
    // This is an optimization that eliminates superfluous rerenders/fetching by
    // keeping a copy of the `products` array prop in state for shallow comparison.
    if (!Array.isArray(products)) {
      return;
    }
    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
      setProducts(products);
    }
  }, [products]);

  useEffect(() => {
    if (isOnScreen && recommendations?.recs) {
      sendViewReco(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
      dataCloud.sendViewRecommendations(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
    }
  }, [isOnScreen, recommendations]);

  // SFCC-83 — Recently Viewed only. Every other recommender falls through to the unchanged
  // ProductScroller branch below. Moved ahead of the dead-check below (build plan A6, bug fix #3,
  // 2026-09-08 revision) — see this file's own module docblock for the full "why". In short: this
  // branch's cards no longer come from `recommendations` at all (see the effect above, bug fix
  // #2), so `recommendations`/`isLoading` stay at `useEinstein()`'s own untouched initial state
  // (`[]`/`false`) for this recommender, which would make the dead-check below evaluate `true`
  // unconditionally (via its `recommendations.length < 1` clause specifically, since
  // `recommendations` itself stays a truthy `[]`, never falsy) and return `null` regardless of
  // `hasRecentlyViewed` if this branch still ran after it. Every other recommender is unaffected
  // by the reordering — they still hit the exact same dead-check + ProductScroller path below,
  // unchanged, just after this check now short-circuits past them when it applies.
  if (recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED) {
    // Cart exclusion (2026-09-10, Marcel) — see the isCartPage constant's own comment above for
    // why this can't be expressed as a distinct recommender value. No rail, no title, no
    // placeholder — same treatment as the empty-state gate below, just for a different reason.
    if (isCartPage) {
      return null;
    }

    // AC 8's empty-state gate — see useRecentlyViewedHistory.ts's own docblock. No rail, no
    // title, no placeholder.
    if (!hasRecentlyViewed) {
      return null;
    }

    // `recentlyViewedProducts` is real, strongly-typed Commerce API data (see
    // recentlyViewedProductFetch.ts), unlike the old `recommendations.recs` chain this replaces —
    // nothing here is `any`, so (unlike the untouched `.find`/`.some`/`.map` callbacks elsewhere
    // in this file, which still read off `useEinstein()`'s untyped `recommendations`) no step of
    // this chain needs an explicit parameter-type annotation to satisfy `noImplicitAny`.
    const cards: ZimmProductCardProps[] = recentlyViewedProducts
      .map((product) => selectRecentlyViewedCard(product, formatPrice))
      .filter((card: RecentlyViewedCard | null): card is RecentlyViewedCard => card !== null)
      .map(
        (card: RecentlyViewedCard): ZimmProductCardProps => ({
          ...card,
          // Inert for this variation — ZimmProductCardContent never mounts when
          // variation: 'recentlyViewed' (zimmProductCard/index.tsx's
          // VARIATION_CONFIG.showContent). 'h3' matches the one other established value for
          // this same required field (product-list/productListCardMapper.ts).
          headingLevel: 'h3',
          variation: 'recentlyViewed',
        }),
      );

    // The See-Full-History link, finally wired in (was a stated "not yet built" gap on every
    // caller until now). Triggers when the shopper has more recently-viewed products
    // than fit in view at the *current* breakpoint — matching the AC's own "exceeds the visible
    // rail width" wording, which is viewport-relative, not a flat count. Compared against
    // `cards.length` (the full, unsliced count this container just built — up to
    // RECENTLY_VIEWED_HISTORY_MAX_STORED, 24), not the rail's own internal 5-item render slice,
    // since the question is "does more exist than is visible", not "did we cap the render".
    const showSeeAllLink = cards.length > visibleCardCount;

    return (
      // Ref-attachment point — see the module docblock's own isOnScreen/forwardRef note above for
      // why this wrapper exists at all. `{...props}` forwards the caller's own layout props (e.g.
      // PDP's `mx={{base: -4, md: -8, lg: 0}}`, Cart's `mx={{base: -4, sm: -6, lg: 0}}`) exactly
      // as the ProductScroller branch below already does — without it, this branch would render
      // inset inside the page's normal content padding while every sibling rail on the same page
      // bleeds edge-to-edge, and zimmRecentlyViewedRail.css.ts's own card-width math (e.g.
      // 201x2=402) assumes the full viewport width is actually available. `title` is passed
      // straight through, no `recommendations?.displayMessage` fallback — `recommendations` is
      // never populated for this branch (see above), and this component owns no copy of its own
      // (build plan A5/A6): the real title always comes from the caller.
      <Box ref={ref} {...(props as BoxProps)}>
        <ZimmRecentlyViewedRail
          title={title}
          cards={cards}
          seeAllHref={showSeeAllLink ? buildUrl(RECENTLY_VIEWED_ROUTE) : undefined}
          seeAllLabel={showSeeAllLink ? intl.formatMessage(messages.seeFullHistory) : undefined}
        />
      </Box>
    );
  }

  // The component should remove itself altogether if it has no recommendations
  // and we aren't loading any.
  if (!isLoading && (!recommendations || recommendations.length < 1)) {
    return null;
  }

  // TODO: DRY this handler when intl provider is available globally
  const addItemToWishlist = async (product: RecommendedProduct) => {
    try {
      if (!wishlist || !customerId) {
        return;
      }
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          customerId,
        },
        body: {
          quantity: 1,
          productId: product.productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });

      toast({
        title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
        status: 'success',
        action: (
          // it would be better if we could use <Button as={Link}>
          // but unfortunately the Link component is not compatible
          // with Chakra Toast, since the ToastManager is rendered via portal
          // and the toast doesn't have access to intl provider, which is a
          // requirement of the Link component.
          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
            {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
          </Button>
        ),
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  const removeItemFromWishlist = async (product: RecommendedProduct) => {
    try {
      const wishlistItem = wishlist?.customerProductListItems?.find(
        (item: { productId?: string }) => item.productId === product.productId,
      );
      if (!wishlistItem || !wishlist || !customerId) {
        return;
      }
      await deleteCustomerProductListItem.mutateAsync({
        parameters: {
          customerId,
          itemId: wishlistItem.id,
          listId: wishlist.id,
        },
      });
      toast({
        title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
        status: 'success',
        id: product.productId,
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  return (
    <ProductScroller
      ref={ref}
      title={title || recommendations?.displayMessage}
      products={recommendations.recs}
      isLoading={isLoading}
      productTileProps={(product: RecommendedProduct) => ({
        onClick: () => {
          sendClickReco(
            {
              recommenderName: recommendations.recommenderName,
              __recoUUID: recommendations.recoUUID,
            },
            product,
          );
        },
        enableFavourite: true,
        isFavourite: wishlist?.customerProductListItems?.some(
          (item: { productId?: string }) => item.productId === product?.productId,
        ),
        onFavouriteToggle: (toBeFavourite: boolean) => {
          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
          return action(product);
        },
      })}
      {...props}
    />
  );
};

export default RecommendedProducts;

/**
 * The "given IDs, fetch real product data" half of SFCC-83/84's interim Recently Viewed data
 * source (build plan §2, "Interim data source" — Einstein is "Not Deployed" on every real
 * Zimmermann site, so this build ships against a browser-tracked view-history stand-in instead).
 * The companion piece is `useRecentlyViewedHistory`
 * (`overrides/app/hooks/useRecentlyViewedHistory.ts`), which supplies the `ids` this hook
 * consumes — every product this hook returns is real, live Commerce Cloud data; only the list of
 * *which* IDs to fetch is sourced from this browser's own tracked history rather than Einstein.
 *
 * Wraps `useProducts` (`@salesforce/commerce-sdk-react`, confirmed real export at
 * `node_modules/@salesforce/commerce-sdk-react/hooks/ShopperProducts/query.js`, re-exported from
 * the package root — the same hook already used at
 * `overrides/app/pages/product-detail/index.tsx:334`), which calls the Shopper Products
 * `getProducts` endpoint. Parameters (`allImages: true`, `perPricebook: true`, `expand: [
 * 'prices', 'promotions', 'images', 'variations']`) match the combination already confirmed
 * correct three independent times this build (Einstein's own `fetchRecProductDetails`
 * — `@salesforce/retail-react-app/app/hooks/use-einstein.js:465-505` — the PLP quick-test mapper,
 * and the `zimmproductcard-live-demo` branch's real-product search call).
 *
 * **The 24-ID cap is a real, hard API limit, not a preference.** Confirmed directly in the SDK's
 * own doc comment: `node_modules/@salesforce/commerce-sdk-react/hooks/ShopperProducts/query.js:29`
 * — *"The maximum number of productIDs that can be requested are 24."* — restated independently
 * in `commerce-sdk-isomorphic`'s own type-declaration prose
 * (`node_modules/commerce-sdk-isomorphic/lib/index.esm.d.ts:58802`: *"hydrate a list of products
 * (max 24)"*). Marcel's explicit decision: cap to the first `GET_PRODUCTS_MAX_IDS_PER_REQUEST`
 * ids, don't batch into multiple requests — a shopper with more than 24 tracked IDs simply never
 * gets the tail of their history fetched by this hook.
 *
 * **SDK param widening for `ids`.** `getProductsQueryParameters.ids` types as `Array<string>`
 * throughout `commerce-sdk-isomorphic` (confirmed at `index.esm.d.ts:57797` and `:58753`), but the
 * real, working base SFCC call this build models (`use-einstein.js`'s `fetchRecProductDetails`)
 * passes a comma-joined string (`ids.join(',')`) straight through — the SDK forwards it verbatim
 * into the query string regardless of the declared array type. This file follows the exact same
 * precedent already used elsewhere in this codebase for this exact field:
 * `overrides/app/pages/product-detail/index.tsx:339`
 * (`ids: childVariantIds.join(',') as unknown as string[]`, commented there as "SDK param
 * widening").
 */
import { useProducts } from '@salesforce/commerce-sdk-react';
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';

/**
 * Hard per-request limit on the Shopper Products `getProducts` endpoint — see this file's own
 * docblock above for the two independent SDK citations confirming this number. Not a UX/product
 * choice, and not adjustable client-side.
 */
const GET_PRODUCTS_MAX_IDS_PER_REQUEST = 24;

export type RecentlyViewedProductFetchResult = {
  /**
   * Real Shopper Products data for as many of the requested (capped) `ids` as the API actually
   * returned, **re-ordered to match `ids`'s own order** — the API's own response order is not
   * documented or guaranteed to match request order, so this hook does the re-ordering rather
   * than assume it. An id the API didn't return at all (e.g. offline or deleted since it was
   * viewed) is silently dropped, not left as a hole in the array.
   */
  products: readonly ShopperProductsTypes.Product[];
  /** `true` only while a real fetch is in flight for a non-empty id list — deliberately `false`,
   *  not the underlying query's own (potentially permanently-pending) loading state, when there
   *  are no ids to fetch at all, since no request is ever made in that case. */
  isLoading: boolean;
};

/**
 * Given a list of product IDs (most-recent-first, per `useRecentlyViewedHistory`), fetches real,
 * live Commerce Cloud product data for them.
 *
 * @param ids - Product IDs to fetch, most-recent-first. A list longer than
 *   `GET_PRODUCTS_MAX_IDS_PER_REQUEST` is truncated to the first N (Marcel's cap-don't-batch
 *   decision) — the endpoint itself has no way to serve more in a single call.
 * @returns `products` — real product data for the requested ids, re-ordered to match `ids` and
 *   with any id the API didn't return dropped. `isLoading` — whether a real fetch is in flight.
 */
export const useRecentlyViewedProductFetch = (ids: readonly string[]): RecentlyViewedProductFetchResult => {
  const cappedIds = ids.slice(0, GET_PRODUCTS_MAX_IDS_PER_REQUEST);

  const { data, isLoading: queryIsLoading } = useProducts(
    {
      parameters: {
        // SDK param widening -- see this file's own docblock for why a comma-joined string is
        // correct here despite the declared `Array<string>` type.
        ids: cappedIds.join(',') as unknown as string[],
        allImages: true,
        perPricebook: true,
        expand: ['prices', 'promotions', 'images', 'variations'],
      },
    },
    {
      // Matches the existing precedent at product-detail/index.tsx:347 for this same hook: don't
      // fire a request at all when there's nothing to ask for.
      enabled: cappedIds.length > 0,
    },
  );

  const productsById = new Map((data?.data ?? []).map((product) => [product.id, product] as const));
  const products = cappedIds
    .map((id) => productsById.get(id))
    .filter((product): product is ShopperProductsTypes.Product => product !== undefined);

  return {
    products,
    // A disabled query (no ids) never transitions out of its initial loading state on some
    // TanStack Query versions/configurations -- AND against `cappedIds.length > 0` so "loading"
    // never lies about a fetch that was never actually started.
    isLoading: cappedIds.length > 0 && queryIsLoading,
  };
};

/**
 * Maps one Recently Viewed product onto the subset of `ZimmProductCard` props the
 * `recentlyViewed` variation (SFCC-83) actually renders.
 *
 * **Input source revised 2026-09-08 (build plan §2, "Interim data source") — Einstein is "Not
 * Deployed" on every real Zimmermann site, so this build ships against a browser-tracked
 * view-history stand-in instead.** Input is now a plain Commerce API `Product`
 * (`commerce-sdk-isomorphic`'s `ShopperProductsTypes.Product`), exactly as returned by
 * `overrides/app/utils/recentlyViewedProductFetch.ts`'s own `getProducts` call (`expand: [
 * 'prices', 'promotions', 'images', 'variations']`, `allImages: true`, `perPricebook: true`) —
 * the same underlying Shopper Products shape the original Einstein-sourced design used, minus the
 * Einstein-specific `rec`/flat-`image` wrapper fields `fetchRecProductDetails`
 * (`@salesforce/retail-react-app/app/hooks/use-einstein.js:465-505`) used to bolt on. This
 * mapper's own output contract and scope (image-only, no gallery, no was/now pricing — A2's
 * `recentlyViewed` variation decision, unchanged) are unaffected; only the shape of what it reads
 * on the way in changed, and with it, `selectPrimaryImage`'s fallback below: there is no longer a
 * separate flat Einstein image to fall back to, so "the selected `imageGroups` image has no
 * usable `src`" and "there is no usable image at all" are now the same case.
 *
 * Modelled on `overrides/app/pages/product-detail/productInfo.ts` — no React/react-intl import,
 * `formatPrice` injected as a parameter so this module stays independently testable — and on the
 * general shape of `liveProductCardDemoMapper.ts` (`feature/zimmproductcard-live-demo`, not this
 * branch — read for its approach, not imported). Unlike that demo mapper, this is a production
 * path: real `commerce-sdk-isomorphic` SDK types are used directly (AGENTS.md > Type
 * Definitions) — with the Einstein-specific input shape gone, there is no longer any hand-rolled
 * field on the input type at all.
 *
 * Deliberately narrow scope, stated here rather than left as a silent gap: this mapper only ever
 * returns `currentPrice` (an active selling price), not was/now sale-price detection
 * (`originalPrice`) — but that is a scope choice, not a data limitation. **Correction
 * (2026-09-08, pre-dates and is unaffected by the input-source revision above):** an earlier
 * version of this comment claimed the merged Einstein shape "has no equivalent of"
 * `getPriceData`-style pricebook logic — verified inaccurate, and equally true of the plain
 * `getProducts` shape this mapper now reads: `recentlyViewedProductFetch.ts` already requests
 * `perPricebook: true`, so `product.tieredPrices` is present, and base SFCC's `getPriceData`
 * (`app/utils/product-utils.js`) already derives `listPrice`/`isOnSale` from exactly that field —
 * nothing is missing, it's simply not called here. The real reason `originalPrice` isn't mapped is
 * that the `recentlyViewed` variation renders no price at all today (see
 * `zimmProductCard/index.tsx`'s `recentlyViewed` `VARIATION_CONFIG` row — `showContent: false`), so
 * there is nothing for it to feed. Mapping `currentPrice` anyway costs nothing and means a future
 * consumer of this same mapper (e.g. a variation that does render price) isn't blocked on this
 * file being revisited — extending it to also call `getPriceData` at that point would be a small,
 * well-precedented addition, not new pricebook work.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type { ZimmProductCardBaseProps, ZimmProductCardImage } from '../components/ui-kits/organisms/zimmProductCard';

/**
 * The real Commerce API `Product` (`commerce-sdk-isomorphic`'s own `ShopperProductsTypes.Product`
 * — not hand-rolled). A plain alias, not an augmentation: unlike the pre-revision Einstein-sourced
 * shape this replaces, `recentlyViewedProductFetch.ts`'s plain `getProducts` result needs nothing
 * bolted on — `Product.id` is used directly, and there is no separate flat-image field. Kept as a
 * named alias (rather than importing `ShopperProductsTypes.Product` directly at each call site)
 * so this module's own input type has a name that documents its role here.
 */
export type RecentlyViewedProduct = ShopperProductsTypes.Product;

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl,
 *  mirroring `productInfo.ts`'s own `FormatPrice` shape. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The subset of `ZimmProductCardBaseProps` this mapper populates. Deliberately excludes
 * `headingLevel` and `variation` — both are render-context decisions belonging to the container
 * step that maps recs through this mapper and renders the rail (SFCC-83's A6 step), which supplies
 * `headingLevel` uniformly for every card and adds `variation: 'recentlyViewed'` itself when
 * spreading this output into `<ZimmProductCard>` — the rail organism itself (A5) takes already-full
 * `ZimmProductCardProps` objects, so variation must already be set before it sees them. A pure data
 * mapper choosing a heading level would conflate a data concern with a layout one. Also excludes `hoverImage`/`images` — this
 * mapper only ever returns one image (`primaryImage`); see `selectPrimaryImage`'s own docblock
 * for why.
 */
export type RecentlyViewedCard = Pick<
  ZimmProductCardBaseProps,
  'id' | 'href' | 'name' | 'primaryImage' | 'currentPrice'
>;

/** The correctly-sized product image view, per AGENTS.md's image-sizing guidance: never serve an
 *  arbitrary-sized image at thumbnail size. Named rather than inlined per conventions.md's
 *  no-magic-strings rule — this is a real, semantic SFCC image `viewType` key. */
const MEDIUM_VIEW_TYPE = 'medium';

/** The variation-attribute id `filterImageGroups` matches an image group's colour against — same
 *  constant, same reasoning, as `productListCardMapper.ts`'s own. */
const COLOUR_VARIATION_ATTRIBUTE_ID = 'color';

/** The one shape this mapper sorts — whatever `ImageGroup.images` actually holds. */
type ImageGroupImage = NonNullable<ShopperProductsTypes.ImageGroup['images']>[number];

/**
 * Extracts the merchandiser-assigned sequence number baked into a catalog image's own filename
 * (e.g. `.../images/1.4673ts251.gvscp.guava-seascape.jpg` → `1`). Mirrors
 * `productListCardMapper.ts`'s own helper of the same name exactly, same real bug: the array
 * order `filterImageGroups` hands back is not guaranteed to match this sequence — confirmed live
 * on `4673TS251`, whose colour-tagged medium group came back `[2, 1, 3, ...]`, which silently
 * showed the on-model shot (image `2`) as primary instead of the flat-lay shot (always image `1`).
 * Returns `undefined` for a non-numeric filename; `sortByImageSequence` leaves those untouched.
 */
const extractImageSequenceNumber = (src: string): number | undefined => {
  const filename = src.split('/').pop() ?? '';
  const match = /^(\d+)\./.exec(filename);
  return match ? Number(match[1]) : undefined;
};

/** Stable sort by `extractImageSequenceNumber` (guaranteed stable since ES2019) — images with no
 *  numeric filename compare equal and keep their original relative order. */
const sortByImageSequence = (images: ImageGroupImage[]): ImageGroupImage[] =>
  [...images].sort((a, b) => {
    const numA = extractImageSequenceNumber(a.disBaseLink || a.link || '');
    const numB = extractImageSequenceNumber(b.disBaseLink || b.link || '');
    if (numA === undefined || numB === undefined) return 0;
    return numA - numB;
  });

/**
 * Resolves which real colour this product's one image should come from. Only the fallback half of
 * `productListCardMapper.ts`'s own `resolveRepresentativeColour` — there is no
 * `representedProduct` branch here because this input is a plain `ShopperProductsTypes.Product`
 * (from `getProducts`), which has no such field at all (confirmed against the SDK's own type):
 * first orderable variant, else the first variant, is the only strategy available to this mapper.
 * Returns `undefined` when there are no variants at all — `selectPrimaryImage` below then falls
 * back to an unscoped, viewtype-only lookup, never a throw.
 */
const resolveViewedColour = (product: RecentlyViewedProduct): string | undefined => {
  const fallbackVariant = product.variants?.find((variant) => variant.orderable) ?? product.variants?.[0];
  return fallbackVariant?.variationValues?.[COLOUR_VARIATION_ATTRIBUTE_ID];
};

/**
 * Resolves the one image this mapper ever returns. `hoverImage`/`images` are never populated —
 * SFCC-83 AC 3 asks for "the product's index image" (singular), and the `recentlyViewed`
 * variation renders neither a hover-swap nor a gallery (see `zimmProductCard/index.tsx`'s
 * `recentlyViewed` row: `showHoverImageSwap: false`, and its render branch never forwards
 * `images` at all).
 *
 * Uses `filterImageGroups` at `viewType: 'medium'` (a real, correctly-sized product image),
 * **colour-scoped first, then viewtype-only as a fallback** — same two-pass fix, same reasoning,
 * as `productListCardMapper.ts`'s own `selectColourScopedImages`, closing a real bug confirmed
 * live on `4673TS251`: with no colour scoping at all, an older, untagged, genuinely-404 medium
 * group and a newer, correctly colour-tagged one are both candidates, and the untagged one wins by
 * default purely because it happens to sit first in the API's own array order. Scoping by colour
 * excludes the untagged group outright. The fallback pass exists for the opposite real case — a
 * genuinely single-colour product whose one medium group carries no `variationAttributes` tag at
 * all (nothing to disambiguate) — which a strict colour-scoped lookup alone would exclude and
 * return nothing for. Never the reverse: a real colour-scoped match never falls back further, to
 * avoid re-mixing colours.
 *
 * **No flat-image fallback (2026-09-08 input-source revision).** The pre-revision Einstein-merged
 * shape carried its own flat `image.disBaseLink`/`image.alt` (Einstein's own single-reference
 * thumbnail) to fall back to when `imageGroups` filtering came up empty. The plain
 * `getProducts` shape this mapper now reads has no equivalent field at all — `imageGroups` is the
 * only image source there is — so "the selected `imageGroups` image has no usable `src`" and
 * "there is no usable image at all" have collapsed into the same case; both now return `null`.
 *
 * @returns `null` when there is no usable `src`. `ZimmProductCardMediaImage.alt` is required and
 *   non-empty, so there is no safe placeholder card to build without a real image — "no usable
 *   image" is treated the same as "no usable name" in `selectRecentlyViewedCard` below: a hard
 *   gate that yields no card at all. Returning `null` here is the only option that structurally
 *   cannot violate the non-empty-`alt` contract, since there is no returned object for `alt` to
 *   be empty on.
 */
const selectPrimaryImage = (product: RecentlyViewedProduct, productName: string): ZimmProductCardImage | null => {
  const colour = resolveViewedColour(product);

  const colourScopedGroups = colour
    ? (filterImageGroups(product.imageGroups ?? [], {
        viewType: MEDIUM_VIEW_TYPE,
        variationValues: { [COLOUR_VARIATION_ATTRIBUTE_ID]: colour },
      }) as ShopperProductsTypes.ImageGroup[])
    : [];

  const groups =
    colourScopedGroups.length > 0
      ? colourScopedGroups
      : (filterImageGroups(product.imageGroups ?? [], {
          viewType: MEDIUM_VIEW_TYPE,
        }) as ShopperProductsTypes.ImageGroup[]);

  const [groupImage] = sortByImageSequence(groups[0]?.images ?? []);
  if (!groupImage) return null;

  const src = groupImage.disBaseLink || groupImage.link;
  if (!src) return null;

  // ZimmProductCardMediaImage.alt is required and non-empty (unlike base ProductTile's
  // decorative alt: '' convention) — mirrors liveProductCardDemoMapper.ts's own fallback exactly.
  const alt = groupImage.alt?.trim() || productName;
  return { src, alt };
};

/**
 * @param product - A plain Commerce API product from `recentlyViewedProductFetch.ts`'s own
 *   `getProducts` call, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `recentlyViewed` `ZimmProductCard` variation, or `null` when the product
 *   has no usable name or no usable image — never a broken card, never a throw.
 */
export const selectRecentlyViewedCard = (
  product: RecentlyViewedProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedCard | null => {
  if (!product?.name) return null;

  const primaryImage = selectPrimaryImage(product, product.name);
  if (!primaryImage) return null;

  return {
    id: product.id,
    href: productUrlBuilder({ id: product.id }),
    name: product.name,
    primaryImage,
    // No hardcoded fallback currency — if either is absent, skip formatting rather than guess,
    // matching productInfo.ts's own "no hardcoded fallback currency" comment.
    currentPrice:
      typeof product.price === 'number' && product.currency ? formatPrice(product.price, product.currency) : undefined,
  };
};

import React from 'react';
import type { ReactNode } from 'react';
import { chakra, useMultiStyleConfig, useBreakpointValue } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS } from 'app/constants';
import { ZimmProductCard } from '../zimmProductCard';
import type { ZimmProductCardProps } from '../zimmProductCard';

// Same `chakra(RouteLink)` wrap this component family already establishes for its own internal
// links (zimmProductCard/index.tsx's `MediaOnlyCardLink`, zimmProductCardContent/index.tsx's
// `ProductNameLink`) — used here for the See-Full-History link, which navigates to the SFCC-84
// Recently Viewed Full History page, an internal route, not an external URL.
const SeeAllLink = chakra(RouteLink);

export type ZimmRecentlyViewedRailProps = {
  /**
   * Typed as `ReactNode`, not `string` — this component owns no copy/intl (the container, A6,
   * does). **Styling resolved 2026-09-08** (was previously left unstyled pending confirmation —
   * live Storybook testing caught the resulting bug: the title rendered in the ambient body
   * weight, Futura Round 400, instead of the design's intended weight): this component now
   * applies `textStyle="heading3"` itself when rendering `title`, matching the exact spec
   * confirmed against the Full History page's own title bar this same session (Figma
   * `Default/h3-strong` — Futura Round, 16px/18 line-height, weight 500, letter-spacing -0.12px,
   * uppercase — cross-checked against this codebase's registered `heading3` token, an exact
   * match). Applying it here rather than requiring every caller to pre-style the title guarantees
   * the design intent regardless of what a caller passes; a caller supplying an already fully
   * styled element can still override any of this via its own more-specific styling.
   */
  title: ReactNode;
  /**
   * Rendered in the exact order received (AC 2: most-recent-first, left to right) — no sorting or
   * reordering happens here. Capped to `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS` for the current real
   * breakpoint regardless of length — a hard cap, not a "fits before scrolling" soft limit (see
   * that constant's own comment, app/constants/index.ts, and this component's own render-body
   * comment below for why the cap has to live here rather than in the request that produced this
   * array).
   */
  cards: readonly ZimmProductCardProps[];
  /** Href to the SFCC-84 Recently Viewed Full History page. The See-Full-History link only
   *  renders when this is provided — see the render body below. */
  seeAllHref?: string;
  /**
   * No default/fallback text is supplied when this is omitted while `seeAllHref` is provided —
   * this component owns no copy or intl (see the module docblock), so inventing an English
   * fallback here would risk shipping untranslated text on non-English storefronts. In real usage
   * the container (A6) is expected to always supply this alongside `seeAllHref`.
   */
  seeAllLabel?: string;
};

const ZIMM_RECENTLY_VIEWED_RAIL_RECIPE = 'ZimmRecentlyViewedRail';

/**
 * SFCC-83 — the Recently Viewed rail organism (build plan section A5). Purely presentational:
 * data arrives as props, no data-fetching, no `useEinstein`, no `useIntl` — see
 * .claude/rules/components.md's container/presentational split. The container (A6) is
 * responsible for building `cards` (via A3's Einstein-rec-to-card mapper), gating this
 * component's visibility (A4's `hasRecentlyViewed`), and supplying `title`/`seeAllLabel` copy.
 *
 * Structure mirrors Figma exactly: a `header` row (title left, the See-Full-History link right)
 * above a `group` of `ZimmProductCard`s. No rail-level arrow buttons — `ZimmProductCardMedia`
 * already carries its own intra-card carousel arrows, and a second set at the rail level would
 * collide with them (see zimmRecentlyViewedRail.css.ts's own docblock for the Figma node
 * evidence).
 *
 * **`group`'s horizontal scroll/scroll-snap (zimmRecentlyViewedRail.css.ts) is a narrow-viewport
 * safety net, not the "more cards exist, scroll to see them" mechanism it might look like.**
 * Confirmed with Marcel (2026-09-08): the per-breakpoint card count below is a hard cap — a
 * shopper on a real, design-reference-width device never has more cards to scroll to than the
 * cap allows; "more history exists" is surfaced via the See-Full-History link (the container's
 * own job), not via scrolling this rail further. The scroll/scroll-snap CSS stays
 * meaningful only for a real device narrower than the design reference itself (e.g. a phone
 * under ~402px), where the capped card count can still slightly overflow the actual viewport.
 *
 * `cards` is typed as the full `ZimmProductCardProps` union, matching this step's own given
 * component contract verbatim — this component therefore spreads each entry straight into
 * `ZimmProductCard` (`<ZimmProductCard {...card} />`) rather than forcing
 * `variation: 'recentlyViewed'` onto every card itself. In real usage every entry already carries
 * that variation by construction (A3's mapper produces `recentlyViewed`-shaped cards, matching
 * `variation: 'recentlyViewed'` in the type union — see zimmProductCard/index.tsx's
 * `ZimmProductCardRecentlyViewedVariation`) — this component trusts that contract rather than
 * re-asserting it, consistent with staying purely presentational.
 *
 * `data-testid="product-card"` / `data-product-id` on each rendered card come from
 * `ZimmProductCard`'s own root (zimmProductCard/index.tsx: "a DOM hook for QA automation/
 * analytics") — this component adds no additional per-card test hook of its own.
 */
export const ZimmRecentlyViewedRail = ({ title, cards, seeAllHref, seeAllLabel }: ZimmRecentlyViewedRailProps) => {
  const styles = useMultiStyleConfig(ZIMM_RECENTLY_VIEWED_RAIL_RECIPE, {});

  // Cap is enforced here, client-side, regardless of how many cards were passed in — the data
  // source (`useRecentlyViewedHistory` / `recentlyViewedProductFetch.ts`) does not itself honour
  // a requested limit, and per-breakpoint capping is this component's own presentational concern,
  // not the container's. Falls back to the smallest (base/mobile) count on the very first render
  // before Chakra's SSR-safe mount-then-resolve pass settles (see RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS's
  // own comment, app/constants/index.ts, for why this is a hard per-breakpoint cap, not a "fits
  // before scrolling" soft limit). A slice, never a sort — order is otherwise untouched (AC 2).
  const maxVisibleCards =
    useBreakpointValue(RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS) ?? RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base;
  const visibleCards = cards.slice(0, maxVisibleCards);

  // Second guard behind A4's own visibility gate, which lives in the container, not here — an
  // empty rail renders nothing at all, not an empty shell.
  if (visibleCards.length === 0) {
    return null;
  }

  return (
    <chakra.div __css={styles.container} data-testid="recently-viewed-rail">
      <chakra.div __css={styles.header}>
        {/* flex/minWidth match Figma's own title node (flex: 1 0 0, min-w-px) — grows to fill
            whatever `header`'s own gap + the link's width don't claim, and can shrink below its
            own text's intrinsic width rather than force an overflow. See zimmRecentlyViewedRail.css.ts's
            own "TITLE/LINK SPACING" docblock section. */}
        <chakra.span textStyle="heading3" flex="1 0 0" minWidth={0}>
          {title}
        </chakra.span>
        {seeAllHref && seeAllLabel && (
          <SeeAllLink to={seeAllHref} textStyle="linkLg" __css={styles.seeAllLink}>
            {seeAllLabel}
          </SeeAllLink>
        )}
      </chakra.div>
      <chakra.div __css={styles.group} data-testid="recently-viewed-rail-group">
        {visibleCards.map((card) => (
          <chakra.div key={card.id} __css={styles.card}>
            <ZimmProductCard {...card} />
          </chakra.div>
        ))}
      </chakra.div>
    </chakra.div>
  );
};

