import { describe, test, expect, vi, afterEach } from 'vitest';
import { renderHook } from '@testing-library/react';
import { useMediaQuery } from '@chakra-ui/react';
import { useRecentlyViewedRailVisibleCount } from './useRecentlyViewedRailVisibleCount';

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return { ...actual, useMediaQuery: vi.fn() };
});

const mockUseMediaQuery = vi.mocked(useMediaQuery);

/**
 * Guards against the exact regression found 2026-09-10: `useBreakpointValue` can only switch at
 * this site's own registered Chakra breakpoints (`xl` = 1280px), but the rail's own card-width
 * styling switches to Desktop sizing at 1024px — its own real Figma threshold. Between those two
 * numbers, the old approach showed a row already styled for 5 cards while still only allowing 3
 * to render. These tests assert both the query strings themselves (768px/1024px, not
 * breakpoints.xl's 1280px) and the resulting cascade.
 */
describe('useRecentlyViewedRailVisibleCount', () => {
  afterEach(() => {
    vi.clearAllMocks();
  });

  test('queries exactly (min-width: 48em) and (min-width: 64em) — 768px and 1024px, not breakpoints.xl (1280px)', () => {
    mockUseMediaQuery.mockReturnValue([false]);
    renderHook(() => useRecentlyViewedRailVisibleCount());

    expect(mockUseMediaQuery).toHaveBeenCalledWith('(min-width: 48em)');
    expect(mockUseMediaQuery).toHaveBeenCalledWith('(min-width: 64em)');
  });

  test('returns base (2) when neither query matches', () => {
    mockUseMediaQuery.mockReturnValue([false]);
    const { result } = renderHook(() => useRecentlyViewedRailVisibleCount());
    expect(result.current).toBe(2);
  });

  test('returns md (3) when tablet-up matches but desktop (1024px) does not — the exact 1024–1280px gap the bug lived in', () => {
    mockUseMediaQuery.mockImplementation((query: string) => [query === '(min-width: 48em)']);
    const { result } = renderHook(() => useRecentlyViewedRailVisibleCount());
    expect(result.current).toBe(3);
  });

  test('returns xl (5) once the 1024px desktop query matches, regardless of the tablet query', () => {
    mockUseMediaQuery.mockImplementation((query: string) => [query === '(min-width: 64em)']);
    const { result } = renderHook(() => useRecentlyViewedRailVisibleCount());
    expect(result.current).toBe(5);
  });

  test('desktop takes priority over tablet when both queries match (a real ≥1024px viewport matches both)', () => {
    mockUseMediaQuery.mockReturnValue([true]);
    const { result } = renderHook(() => useRecentlyViewedRailVisibleCount());
    expect(result.current).toBe(5);
  });
});

