import { describe, test, expect } from 'vitest';

// PROTOTYPE — not a real file, deleted after this V&V pass. Proposed shared replacement for the
// three duplicated `extractImageSequenceNumber` + `sortByImageSequence` pairs.
const extractImageSequenceNumber = (src: string): number | undefined => {
  const filename = src.split('/').pop() ?? '';
  const match = /^(\d+)\./.exec(filename);
  return match ? Number(match[1]) : undefined;
};

const sortImagesBySequence = <T>(images: readonly T[], getSrc: (image: T) => string): T[] => {
  const numbered = images
    .map((image, index) => ({ image, index, sequence: extractImageSequenceNumber(getSrc(image)) }))
    .filter((entry): entry is { image: T; index: number; sequence: number } => entry.sequence !== undefined)
    .sort((a, b) => a.sequence - b.sequence);

  const numberedSlots = new Set(numbered.map((entry) => entry.index));
  let next = 0;
  return images.map((image, index) => (numberedSlots.has(index) ? numbered[next++].image : image));
};

describe('V&V — proposed sortImagesBySequence replacement', () => {
  test('CodeRabbit adversarial case: mixed numbered/unnumbered now sorts correctly', () => {
    const images = [{ src: '2.a.jpg' }, { src: 'PRODUCT.PZ.jpg' }, { src: '1.a.jpg' }];
    const result = sortImagesBySequence(images, (i) => i.src);
    expect(result.map((i) => i.src)).toEqual(['1.a.jpg', 'PRODUCT.PZ.jpg', '2.a.jpg']);
  });

  test('a harder adversarial case: two unnumbered images interleaved with three numbered ones', () => {
    const images = [
      { src: '3.jpg' },
      { src: 'front.jpg' },
      { src: '1.jpg' },
      { src: 'back.jpg' },
      { src: '2.jpg' },
    ];
    const result = sortImagesBySequence(images, (i) => i.src);
    // Unnumbered stay in their original slots (index 1 and 3); numbered fill the numbered slots
    // (0, 2, 4) in ascending sequence order.
    expect(result.map((i) => i.src)).toEqual(['1.jpg', 'front.jpg', '2.jpg', 'back.jpg', '3.jpg']);
  });

  // Existing passing case from recentlyViewedFullHistoryCard.test.ts / productListCardMapper.test.ts
  // — all-numbered, out-of-order. Must still sort correctly (behaviour-preserving).
  test('all-numbered, out of API order (existing passing case) — unchanged expectation', () => {
    const images = [
      { src: '.../2.product.jpg', alt: 'on model' },
      { src: '.../1.product.jpg', alt: 'flat lay' },
      { src: '.../3.product.jpg', alt: 'side' },
    ];
    const result = sortImagesBySequence(images, (i) => i.src);
    expect(result.map((i) => i.src)).toEqual(['.../1.product.jpg', '.../2.product.jpg', '.../3.product.jpg']);
  });

  // Existing passing case — all-unnumbered, must stay in original order (behaviour-preserving).
  test('all-unnumbered filenames (existing passing case) — unchanged expectation', () => {
    const images = [{ src: '.../PRODUCT.BLK.PZ.jpg' }, { src: '.../PRODUCT.BLK.BZ.jpg' }];
    const result = sortImagesBySequence(images, (i) => i.src);
    expect(result.map((i) => i.src)).toEqual(['.../PRODUCT.BLK.PZ.jpg', '.../PRODUCT.BLK.BZ.jpg']);
  });

  // recentlyViewedCard.ts's own shape: disBaseLink-or-link, not a flat `src` — proving the
  // generic accessor approach actually covers this file's different shape without forcing it to
  // restructure its own pipeline.
  test('recentlyViewedCard.ts shape: disBaseLink-or-link accessor works identically', () => {
    const images = [
      { disBaseLink: undefined, link: '2.a.jpg' },
      { disBaseLink: 'PRODUCT.PZ.jpg', link: undefined },
      { disBaseLink: '1.a.jpg', link: undefined },
    ];
    const result = sortImagesBySequence(images, (i) => i.disBaseLink || i.link || '');
    expect(result.map((i) => i.disBaseLink || i.link)).toEqual(['1.a.jpg', 'PRODUCT.PZ.jpg', '2.a.jpg']);
  });

  test('empty array does not throw', () => {
    expect(sortImagesBySequence([], (i: { src: string }) => i.src)).toEqual([]);
  });

  test('single image does not throw', () => {
    const images = [{ src: '1.jpg' }];
    expect(sortImagesBySequence(images, (i) => i.src).map((i) => i.src)).toEqual(['1.jpg']);
