import { describe, test, expect } from 'vitest';
import { ZimmRecentlyViewedRail } from './zimmRecentlyViewedRail.css';
import { RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT, RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS } from 'app/constants';
import { breakpoints } from 'app/theme/foundation';

/**
 * `index.test.tsx` mocks `useMultiStyleConfig` globally, so this recipe's own object shape is
 * never exercised by any shipped component test — these assertions are the only thing that
 * actually reads it. This is the single most-patched file in the whole SFCC-83/84 feature (three
 * separate same-day live-testing fixes: card sizing, header height/padding, the 1024px-vs-1280px
 * breakpoint mismatch), and it shipped with none of them covered by an automated test — this file
 * closes that gap by locking in the specific values each of those three fixes depends on.
 */
describe('ZimmRecentlyViewedRail — recipe wiring', () => {
  test('every declared part is produced by baseStyle', () => {
    const parts = Object.keys(ZimmRecentlyViewedRail.baseStyle());
    expect(parts.sort()).toEqual([...ZimmRecentlyViewedRail.parts].sort());
  });

  test('the Desktop tier keys off RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT (1024px), not the shared breakpoints.xl (1280px)', () => {
    expect(RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT).toBe('64em');
    expect(breakpoints.xl).toBe('80em');

    const { header, container } = ZimmRecentlyViewedRail.baseStyle() as Record<string, Record<string, unknown>>;
    const desktopKey = `@media (min-width: ${RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT})`;
    const staleXlKey = `@media (min-width: ${breakpoints.xl})`;

    expect(header).toHaveProperty(desktopKey);
    expect(header).not.toHaveProperty(staleXlKey);
    expect(container).toHaveProperty(desktopKey);
  });

  test('header height steps from 56px to 96px at the Desktop tier, not a uniform value', () => {
    const { header } = ZimmRecentlyViewedRail.baseStyle() as Record<string, Record<string, unknown>>;
    const desktopKey = `@media (min-width: ${RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT})`;

    expect(header.height).toBe('3.5rem'); // 56px, base/Mobile/Tablet
    expect((header[desktopKey] as Record<string, unknown>).height).toBe('6rem'); // 96px, Desktop
  });

  test('card width is a computed share of the row tied to the visible-count cap, not a fixed pixel value', () => {
    const { card } = ZimmRecentlyViewedRail.baseStyle() as Record<string, Record<string, unknown>>;
    const tabletKey = `@media (min-width: ${breakpoints.md})`;
    const desktopKey = `@media (min-width: ${RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT})`;

    expect(card.width).toBe(`${(100 / RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base).toFixed(4)}%`);
    expect((card[tabletKey] as Record<string, unknown>).width).toBe(
      `${(100 / RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.md).toFixed(4)}%`,
    );
    expect((card[desktopKey] as Record<string, unknown>).width).toBe(
      `${(100 / RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.xl).toFixed(4)}%`,
    );
    // Guards the original fixed-width regression directly: no per-breakpoint value here may ever
    // be a bare px/rem literal again — every one must derive from the visible-count cap.
    expect(card.width).not.toMatch(/^\d/);
  });

  test('group has zero gap and no scroll-snap CSS — scrolling is not prescribed behaviour for this rail', () => {
    const { group } = ZimmRecentlyViewedRail.baseStyle() as Record<string, Record<string, unknown>>;
    expect(group.gap).toBe(0);
    expect(group).not.toHaveProperty('overflowX');
    expect(group).not.toHaveProperty('scrollSnapType');
  });
});

