describe('resolveFallbackColour', () => {
  test('resolves the first orderable variant colour when one exists', () => {
    const variants = [
      { productId: 'a', orderable: false, variationValues: { color: 'RED' } },
      { productId: 'b', orderable: true, variationValues: { color: 'BLUE' } },
    ];
    expect(resolveFallbackColour(variants, 'color')).toBe('BLUE');
  });

  test('falls back to the first variant at all when none are orderable', () => {
    const variants = [
      { productId: 'a', orderable: false, variationValues: { color: 'RED' } },
      { productId: 'b', orderable: false, variationValues: { color: 'BLUE' } },
    ];
    expect(resolveFallbackColour(variants, 'color')).toBe('RED');
  });

  test('returns undefined when there are no variants', () => {
    expect(resolveFallbackColour(undefined, 'color')).toBeUndefined();
    expect(resolveFallbackColour([], 'color')).toBeUndefined();
  });

  test('reads whichever attribute id the caller passes, not a hardcoded one', () => {
    const variants = [{ productId: 'a', orderable: true, variationValues: { size: 'M' } }];
    expect(resolveFallbackColour(variants, 'size')).toBe('M');
  });
});

