describe('ZimmProductCardMedia — primaryCandidateIndex resets on a colour swap after a prior error (Fix 5 regression)', () => {
  test('a colour swap following a prior image error shows the NEW primary, not a stale fallback from the old colour', () => {
    const FALLBACK_1: ZimmProductCardMediaImage = { src: 'fallback-1.jpg', alt: 'Zimmermann dress, alternate angle' };
    const FALLBACK_2: ZimmProductCardMediaImage = { src: 'fallback-2.jpg', alt: 'Zimmermann dress, another angle' };
    const NEW_PRIMARY: ZimmProductCardMediaImage = { src: 'new-colour-primary.jpg', alt: 'New colour primary' };
    const NEW_FALLBACK: ZimmProductCardMediaImage = { src: 'new-colour-fallback.jpg', alt: 'New colour fallback' };

    const utils = wrap(
      <ZimmProductCardMedia
        primaryImage={PRIMARY}
        primaryImageFallbacks={[FALLBACK_1, FALLBACK_2]}
        swapOnHover={false}
        showControls={false}
      />,
    );
    fireEvent.error(screen.getByRole('img', { name: PRIMARY.alt })); // advances the index to 1

    utils.rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmProductCardMedia
          primaryImage={NEW_PRIMARY}
          primaryImageFallbacks={[NEW_FALLBACK]}
          swapOnHover={false}
          showControls={false}
        />
      </IntlProvider>,
    );

    expect(screen.getByRole('img', { name: NEW_PRIMARY.alt })).toHaveAttribute('src', NEW_PRIMARY.src);
    expect(screen.queryByRole('img', { name: NEW_FALLBACK.alt })).not.toBeInTheDocument();
  });
});

