1	import { useCallback, useEffect, useState } from 'react';
2	import { useCustomerType } from '@salesforce/commerce-sdk-react';
3	import { RECENTLY_VIEWED_HISTORY_MAX_STORED } from 'app/constants';
4	
5	/**
6	 * Storage key backing the Recently Viewed interim history (see `useRecentlyViewedHistory`
7	 * below). Shared by both storage backends (`sessionStorage` for guests, `localStorage` for
8	 * registered shoppers) — safe, since the two are separate namespaces and can never collide.
9	 * Exported as a single named constant so every reader/writer agrees on it, per conventions.md's
10	 * no-magic-strings rule.
11	 *
12	 * Renamed from the pre-revision `RECENTLY_VIEWED_SESSION_KEY` (same literal value): this key now
13	 * holds a JSON-encoded array of product IDs, not a boolean flag string, so the old name no longer
14	 * described its contents.
15	 */
16	export const RECENTLY_VIEWED_HISTORY_STORAGE_KEY = 'zimm-recently-viewed';
17	
18	const EMPTY_IDS: readonly string[] = [];
19	
20	export type RecentlyViewedHistory = {
21	  hasRecentlyViewed: boolean;
22	  recentlyViewedIds: readonly string[];
23	  markProductViewed: (productId: string) => void;
24	};
25	
26	/**
27	 * Reads and parses the stored ID list off a given `Storage`. Tolerant of every failure mode a
28	 * real browser can produce: the key missing entirely, `JSON.parse` failing on corrupt data, a
29	 * parsed value that isn't an array, or the storage access itself throwing (Safari private-
30	 * browsing mode throws on both `sessionStorage` and `localStorage` access, not just on write).
31	 * Every failure degrades to "no history" rather than propagating.
32	 */
33	const readStoredIds = (storage: Storage): string[] => {
34	  try {
35	    const raw = storage.getItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY);
36	    if (!raw) return [];
37	    const parsed: unknown = JSON.parse(raw);
38	    return Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === 'string') : [];
39	  } catch {
40	    return [];
41	  }
42	};
43	
44	/**
45	 * Writes the given ID list to a `Storage`, JSON-encoded. Wrapped in try/catch: Safari private-
46	 * browsing mode throws on `setItem`, and a real device can also legitimately hit a storage quota.
47	 * Either way this degrades to "no write happens" rather than throwing further and breaking the
48	 * PDP view-tracking effect this is called from.
49	 *
50	 * @returns `true` if the write succeeded, `false` if it was silently swallowed.
51	 */
52	const writeStoredIds = (storage: Storage, ids: readonly string[]): boolean => {
53	  try {
54	    storage.setItem(RECENTLY_VIEWED_HISTORY_STORAGE_KEY, JSON.stringify(ids));
55	    return true;
56	  } catch {
57	    return false;
58	  }
59	};
60	
61	/**
62	 * Moves `productId` to the front of `ids`, removing any existing occurrence first (never a
63	 * duplicate — a re-view of an already-seen product correctly becomes "most recent" again), then
64	 * trims to `RECENTLY_VIEWED_HISTORY_MAX_STORED`, oldest-first (i.e. from the tail).
65	 */
66	const dedupeAndPrepend = (ids: readonly string[], productId: string): string[] => {
67	  const withoutExisting = ids.filter((id) => id !== productId);
68	  return [productId, ...withoutExisting].slice(0, RECENTLY_VIEWED_HISTORY_MAX_STORED);
69	};
70	
71	/**
72	 * SFCC-83/84 build plan step A4, **revised 2026-09-08** (Einstein is "Not Deployed" on every real
73	 * Zimmermann site — see the build plan's §2 "Interim data source"): this hook is the temporary,
74	 * browser-tracked stand-in for Einstein's own view-history tracking. It answers two questions:
75	 * "has this shopper viewed anything?" (`hasRecentlyViewed`, `recentlyViewedIds`) and "record that
76	 * this product was just viewed" (`markProductViewed`) — both backed by this browser's own
77	 * storage rather than a server-side recommendation engine.
78	 *
79	 * **The boolean logic, and why it changed from the pre-revision hook this file replaces
80	 * (`useRecentlyViewedGate.ts`):** the old design was
81	 * `hasRecentlyViewed = sessionFlagIsSet || isRegistered` — a deliberate short-circuit trusting
82	 * that a logged-in shopper has *some* server-side Einstein history even on a fresh device. That
83	 * assumption does not hold once Einstein is out of the loop: there is no server-side history left
84	 * to trust. Built with the old formula, every registered shopper would show
85	 * `hasRecentlyViewed: true` unconditionally — including one who has never viewed anything in this
86	 * interim system on any device — gating the rail *open* with zero real cards behind it. The
87	 * corrected formula is purely derived from this interim system's own tracked history, for guests
88	 * and registered shoppers alike:
89	 *
90	 * `hasRecentlyViewed = recentlyViewedIds.length > 0`
91	 *
92	 * `isRegistered` (from `useCustomerType()`, `@salesforce/commerce-sdk-react/hooks/
93	 * useCustomerType.js` — the same hook `@salesforce/retail-react-app/app/hooks/use-einstein.js:449`
94	 * already calls) still matters, just for a different purpose now: it selects *which* storage to
95	 * read/write, not whether to bypass the check.
96	 *
97	 * **Storage split:** `sessionStorage` for guests (genuinely session-scoped, cleared at session
98	 * end — AC 6, unchanged from the pre-revision design) and `localStorage` for registered shoppers.
99	 * The `localStorage` choice is a known, stated, temporary gap, not a fix for AC 7
100	 * ("available on login from any device"): `localStorage` survives closing the browser but is
101	 * still device-local, so it cannot satisfy cross-device continuity. See the build plan's §2 for
102	 * the full reasoning — this is carried in the PR body, not silently tested against one device and
103	 * called passing.
104	 *
105	 * SSR-safe by construction: both `recentlyViewedIds` and the derived `hasRecentlyViewed` start
106	 * empty/`false` on every render and are only ever resolved inside the effect below, so there is
107	 * no storage access during the render pass SSR reproduces — no hydration mismatch, since the rail
108	 * this gates does not exist on first paint either way.
109	 *
110	 * @returns `hasRecentlyViewed` — `true` once this browser has recorded at least one viewed
111	 *   product in the appropriate store, `false` otherwise (including on the very first render,
112	 *   before this hook's own effect has resolved). `recentlyViewedIds` — the stored IDs,
113	 *   most-recent-first. `markProductViewed` — call with a product ID to record a view; safe to
114	 *   call unconditionally, never throws.
115	 */
116	export const useRecentlyViewedHistory = (): RecentlyViewedHistory => {
117	  const { isRegistered } = useCustomerType();
118	  const [recentlyViewedIds, setRecentlyViewedIds] = useState<readonly string[]>(EMPTY_IDS);
119	
120	  useEffect(() => {
121	    const storage = isRegistered ? localStorage : sessionStorage;
122	    setRecentlyViewedIds(readStoredIds(storage));
123	  }, [isRegistered]);
124	
125	  const markProductViewed = useCallback(
126	    (productId: string): void => {
127	      const storage = isRegistered ? localStorage : sessionStorage;
128	      const next = dedupeAndPrepend(readStoredIds(storage), productId);
129	      if (writeStoredIds(storage, next)) {
130	        setRecentlyViewedIds(next);
131	      }
132	    },
133	    [isRegistered],
134	  );
135	
136	  return {
137	    hasRecentlyViewed: recentlyViewedIds.length > 0,
138	    recentlyViewedIds,
139	    markProductViewed,
140	  };
141	};
142

