{"url":"https://api.github.com/repos/ZimmermannAU/zimmermann-pwa/pulls/comments/4012709323","pull_request_review_id":5206426418,"id":4012709323,"node_id":"PRRC_kwDOTJJNGs7vLRXL","diff_hunk":"@@ -242,9 +242,16 @@ describe('ZimmProductCardContent — size-chip slot (PLP only)', () => {
 });

 describe('ZimmProductCardContent — notify-me control', () => {
-  test('is absent when showNotifyMe is true but onNotifyMe is not supplied', () => {
+  // Changed 2026-09-08, Marcel's explicit decision (see this component's own `showNotifyMeButton`
+  // comment): the real Notify Me feature has no handler to wire yet, so the button now ships
+  // visible-but-inert on `showNotifyMe` alone, rather than requiring a real `onNotifyMe` too.
+  test('renders, inert, when showNotifyMe is true and onNotifyMe is not supplied', async () => {
+    const user = userEvent.setup();
     wrap(<ZimmProductCardContent {...BASE_PROPS} showNotifyMe />);
-    expect(screen.queryByRole('button', { name: 'Notify me' })).not.toBeInTheDocument();
+    const button = screen.getByRole('button', { name: 'Notify me' });
+    expect(button.tagName).toBe('BUTTON');
+    // Genuinely inert, not merely present: a real click must not throw with no handler wired.
+    await expect(user.click(button)).resolves.not.toThrow();","path":"overrides/app/components/ui-kits/molecules/zimmProductCardContent/index.test.tsx","commit_id":"c6a7950f1e7ab45c33f75fad2a345a3c577f6491","original_commit_id":"a4b2fe73512cd7a55332d0b5be67fa417d408923","user":{"login":"marcelannavarro","id":297056661,"node_id":"U_kgDOEbS5lQ","avatar_url":"https://avatars.githubusercontent.com/u/297056661?v=4","gravatar_id":"","url":"https://api.github.com/users/marcelannavarro","html_url":"https://github.com/marcelannavarro","followers_url":"https://api.github.com/users/marcelannavarro/followers","following_url":"https://api.github.com/users/marcelannavarro/following{/other_user}","gists_url":"https://api.github.com/users/marcelannavarro/gists{/gist_id}","starred_url":"https://api.github.com/users/marcelannavarro/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/marcelannavarro/subscriptions","organizations_url":"https://api.github.com/users/marcelannavarro/orgs","repos_url":"https://api.github.com/users/marcelannavarro/repos","events_url":"https://api.github.com/users/marcelannavarro/events{/privacy}","received_events_url":"https://api.github.com/users/marcelannavarro/received_events","type":"User","user_view_type":"public","site_admin":false},"body":"Confirmed real and fixed in 522980b — this assertion could never fail even if the handler genuinely threw. Worth noting: the suggested replacement (a bare awaited click, no special assertion) was tested directly and found to be equally unable to catch it in this stack — a handler that throws synchronously during dispatchEvent() never propagates to reject the click's returned promise, which is real DOM-dispatch behaviour, not a testing-library quirk. Fixed instead by spying on console.error around the click, since that's where jsdom's virtual console actually surfaces the uncaught error — same technique already used elsewhere in this suite (resolveByRegion.test.ts). Mutation-tested: forced the real handler to throw, confirmed the new assertion catches it where the old one and the suggested fix both didn't.","created_at":"2026-09-15T06:38:28Z","updated_at":"2026-09-15T06:38:28Z","html_url":"https://github.com/ZimmermannAU/zimmermann-pwa/pull/116#discussion_r4012709323","pull_request_url":"https://api.github.com/repos/ZimmermannAU/zimmermann-pwa/pulls/116","_links":{"self":{"href":"https://api.github.com/repos/ZimmermannAU/zimmermann-pwa/pulls/comments/4012709323"},"html":{"href":"https://github.com/ZimmermannAU/zimmermann-pwa/pull/116#discussion_r4012709323"},"pull_request":{"href":"https://api.github.com/repos/ZimmermannAU/zimmermann-pwa/pulls/116"}},"reactions":{"url":"https://api.github.com/repos/ZimmermannAU/zimmermann-pwa/pulls/comments/4012709323/reactions","total_count":0,"+1":0,"-1":0,"laugh":0,"hooray":0,"confused":0,"heart":0,"rocket":0,"eyes":0},"start_line":null,"original_start_line":null,"start_side":null,"line":null,"original_line":254,"side":"RIGHT","in_reply_to_id":4012275067,"author_association":"MEMBER","original_position":15,"position":1,"subject_type":"line"}

